const TA_DATA=[[["ORDER",0,"t"],"நியூரான் (நரம்பு செல்): உங்கள் மூளையின் தூதுவர்"],[["ORDER",0,"u"],"சுமார் 86 பில்லியன் நியூரான்கள் சிறிய மின் துடிப்புகளாகவும் வேதியியல் செய்திகளாகவும் சமிக்ஞைகளைக் கடத்துகின்றன. ஒவ்வொரு எண்ணமும், உணர்வும், பழக்கமும் ஒன்றாகச் சேர்ந்து இயங்கும் நியூரான்களின் ஒரு வடிவமே."],[["ORDER",0,"steps",0],"டென்ட்ரைட்டுகள் சமிக்ஞைகளைப் பெறுகின்றன"],[["ORDER",0,"steps",1],"செல் உடல் அவற்றைக் கூட்டுகிறது"],[["ORDER",0,"steps",2],"எல்லை அளவை எட்டுகிறது: நியூரான் இயங்குகிறது"],[["ORDER",0,"steps",3],"சமிக்ஞை ஆக்சான் வழியாக வேகமாகப் பாய்கிறது"],[["ORDER",0,"steps",4],"சினாப்ஸில் வேதியியல் செய்தி வெளியிடப்படுகிறது"],[["ORDER",0,"keys",0,0],"டென்ட்ரைட்டுகள்"],[["ORDER",0,"keys",0,1],"உள்ளே வரும் சமிக்ஞைகளைக் கேட்கும் கிளைகள்"],[["ORDER",0,"keys",1,0],"ஆக்சான்"],[["ORDER",0,"keys",1,1],"சமிக்ஞையை வெளியே கொண்டு செல்லும் நீண்ட கம்பி"],[["ORDER",0,"keys",2,0],"மையலின்"],[["ORDER",0,"keys",2,1],"சமிக்ஞையை வேகப்படுத்தும் கொழுப்பாலான காப்பு உறை"],[["ORDER",0,"keys",3,0],"செயல் மின்னழுத்தம் (ஆக்ஷன் பொட்டன்ஷியல்)"],[["ORDER",0,"keys",3,1],"“முழுதும் அல்லது ஒன்றுமில்லை” என்ற மின் துடிப்பு"],[["ORDER",0,"tr",0],"நீங்கள் அடிக்கடி நினைக்கும் ஒரு எண்ணத்தை, ஒளிரும் நியூரான்களின் சங்கிலியாகக் கற்பனை செய்யுங்கள்"],[["ORDER",0,"tr",1],"நினைவில் வையுங்கள்: ஒவ்வொரு முறை திரும்பச் செய்யும்போதும் அந்தச் சங்கிலி இயங்குவது இன்னும் சற்று எளிதாகிறது"],[["ORDER",0,"rl"],"மிகச் சிறிய அளவிலும் நீங்கள் இணைப்புக்காகவே உருவாக்கப்பட்டிருக்கிறீர்கள்: நியூரான்கள் மற்ற நியூரான்களோடு உறவில் இருக்கும்போது மட்டுமே வேலை செய்கின்றன."],[["ORDER",0,"simple"],"உங்கள் மூளையில் நியூரான்கள் என்ற கோடிக்கணக்கான சிறிய தூதுவர்கள் இருக்கிறார்கள். நீங்கள் யோசிக்கவும், உணரவும், அசையவும் உதவ அவை ஒன்றுக்கொன்று சிறிய தீப்பொறிகளைக் கடத்துகின்றன."],[["ORDER",1,"t"],"சினாப்ஸ்: கற்றல் நடக்கும் இடம்"],[["ORDER",1,"u"],"சினாப்ஸ் என்பது நியூரான்களுக்கு இடையே உள்ள சிறிய இடைவெளி. கற்றல், சமிக்ஞைகள் அதைக் கடக்கும் வலிமையை மாற்றுகிறது. மூளை மாற்றியமைக்கப்படுவது உண்மையில் இங்கேதான் நடக்கிறது."],[["ORDER",1,"steps",0],"சமிக்ஞை வந்து சேர்கிறது"],[["ORDER",1,"steps",1],"நரம்பியக்கடத்திகள் வெளியிடப்படுகின்றன"],[["ORDER",1,"steps",2],"அவை இடைவெளியைக் கடக்கின்றன"],[["ORDER",1,"steps",3],"ஏற்பிகள் அவற்றைப் பிடித்துக்கொள்கின்றன"],[["ORDER",1,"steps",4],"அடுத்த நியூரான் இயங்குகிறது (அல்லது இயங்காது)"],[["ORDER",1,"steps",5],"அடிக்கடி பயன்படுத்துவது இணைப்பை வலுப்படுத்துகிறது"],[["ORDER",1,"keys",0,0],"நரம்பியக்கடத்தி"],[["ORDER",1,"keys",0,1],"வேதியியல் தூதுவர் (உதாரணமாக டோபமைன், செரோடோனின், GABA)"],[["ORDER",1,"keys",1,0],"ஏற்பி (ரிசெப்டர்)"],[["ORDER",1,"keys",1,1],"தூதுவர் பொருந்தும் “பூட்டு”"],[["ORDER",1,"keys",2,0],"சினாப்ஸ் வலிமை"],[["ORDER",1,"keys",2,1],"ஒரு நியூரான் அடுத்ததை எவ்வளவு எளிதாக இயக்குகிறது"],[["ORDER",1,"keys",3,0],"LTP"],[["ORDER",1,"keys",3,1],"நீண்டகால வலுவூட்டல் (Long-term potentiation): பயன்பாட்டின் மூலம் ஒரு சினாப்ஸ் நீடித்து வலுப்படுதல்"],[["ORDER",1,"tr",0],"“பயிற்சி” என்பதற்கு உண்மையில் சினாப்ஸ்களை வலுப்படுத்துதல் என்றே அர்த்தம் என்பதைக் கவனியுங்கள்"],[["ORDER",1,"tr",1],"புதிய இணைப்புகளை உருவாக்க, கடுமையான தீவிரத்தை விட அன்பான திரும்பத் திரும்பச் செய்தலே சிறந்தது"],[["ORDER",1,"rl"],"அரிதாக நடக்கும் பெரிய தருணங்களை விட, சிறிய, உண்மையுள்ள அன்றாடச் செயல்களே நம்மை அதிகம் உருவாக்குகின்றன."],[["ORDER",1,"simple"],"சினாப்ஸ் என்பது இரண்டு நியூரான்களுக்கு இடையிலான சிறிய இடைவெளி. நீங்கள் ஒன்றைப் பயிற்சி செய்யும் ஒவ்வொரு முறையும், செய்தி இன்னும் எளிதாகத் தாண்டிச் செல்கிறது. அதுதான் கற்றல்!"],[["ORDER",2,"t"],"நரம்பியல் நெகிழ்வு: மாறும் மூளை"],[["ORDER",2,"u"],"நரம்பியல் நெகிழ்வு (மூளை மாறும் திறன்) என்பது வாழ்நாள் முழுவதும் மூளை தன்னைத் தானே மறுசீரமைத்துக்கொள்ளும் திறன்: புதிய இணைப்புகளை உருவாக்குதல், பயன்படும் இணைப்புகளை வலுப்படுத்துதல், பயன்படாதவற்றை வலுவிழக்கச் செய்தல்."],[["ORDER",2,"steps",0],"அனுபவம் அல்லது பயிற்சி"],[["ORDER",2,"steps",1],"நியூரான்கள் ஒன்றாக இயங்குகின்றன"],[["ORDER",2,"steps",2],"இணைப்புகள் வலுப்படுகின்றன"],[["ORDER",2,"steps",3],"புதிய வடிவம் உருவாகிறது"],[["ORDER",2,"steps",4],"அந்த வடிவம் எளிதாகிறது"],[["ORDER",2,"steps",5],"புதிய இயல்புநிலை"],[["ORDER",2,"keys",0,0],"அனுபவத்தைச் சார்ந்தது"],[["ORDER",2,"keys",0,1],"நீங்கள் திரும்பத் திரும்பச் செய்வது, நினைப்பது, உணர்வதற்கு ஏற்ப மூளை மாறுகிறது"],[["ORDER",2,"keys",1,0],"வாழ்நாள் முழுவதும்"],[["ORDER",2,"keys",1,1],"பெரியவர்களான பிறகும் நெகிழ்வு தொடர்கிறது, ஆனால் மாற்றத்துக்குத் திரும்பத் திரும்பச் செய்தல் தேவை"],[["ORDER",2,"keys",2,0],"இரு வழிகளிலும்"],[["ORDER",2,"keys",2,1],"நெகிழ்வு ஆரோக்கியமான வடிவங்களையும் வலுப்படுத்தலாம், ஆரோக்கியமற்றவற்றையும் வலுப்படுத்தலாம்"],[["ORDER",2,"keys",3,0],"கவனம்"],[["ORDER",2,"keys",3,1],"கூர்ந்த கவனமும் உணர்வும் எவ்வளவு மாற்றம் நடக்கிறது என்பதை அதிகரிக்கின்றன"],[["ORDER",2,"tr",0],"தினமும் பயிற்சி செய்ய ஒரு சிறிய புதிய பதில்செயலைத் தேர்ந்தெடுங்கள்"],[["ORDER",2,"tr",1],"அதோடு கவனத்தையும் கொஞ்சம் நல்ல உணர்வையும் சேர்த்துக்கொள்ளுங்கள்"],[["ORDER",2,"tr",2],"இயல்பாக உணர்வதற்கு முன் அது சங்கடமாக இருக்கும் என்று எதிர்பாருங்கள்"],[["ORDER",2,"rl"],"நம்பிக்கைக்கு ஒரு உயிரியல் அடிப்படை உண்டு: நீங்கள் படைக்கப்பட்ட விதத்திலேயே மாற்றம் கட்டமைக்கப்பட்டிருக்கிறது."],[["ORDER",2,"simple"],"உங்கள் மூளை வாழ்நாள் முழுவதும் மாறவும் வளரவும் முடியும். நீங்கள் திரும்பத் திரும்பப் பயிற்சி செய்வது எளிதாகிறது."],[["ORDER",3,"t"],"ஒன்றாக இயங்கினால், ஒன்றாக இணையும்"],[["ORDER",3,"u"],"நியூரான்கள் திரும்பத் திரும்ப ஒரே நேரத்தில் இயங்கும்போது, அவற்றுக்கிடையேயான இணைப்பு வலுப்படுகிறது (ஹெப்பின் விதி). இது சூழ்நிலைகளை உணர்வுகளோடும் பழக்கங்களோடும் இணைக்கிறது."],[["ORDER",3,"steps",0],"இரண்டு விஷயங்கள் ஒன்றாக நடக்கின்றன"],[["ORDER",3,"steps",1],"நியூரான்கள் ஒன்றாக இயங்குகின்றன"],[["ORDER",3,"steps",2],"இணைப்பு வலுப்படுகிறது"],[["ORDER",3,"steps",3],"இப்போது ஒன்று மற்றொன்றைத் தூண்டுகிறது"],[["ORDER",3,"steps",4],"தானியங்கித் தொடர்பு"],[["ORDER",3,"keys",0,0],"ஹெப்பியன் கற்றல்"],[["ORDER",3,"keys",0,1],"“ஒன்றாக இயங்கும் செல்கள் ஒன்றாக இணைகின்றன” (Donald Hebb, 1949)"],[["ORDER",3,"keys",1,0],"தொடர்புபடுத்தல்"],[["ORDER",3,"keys",1,1],"முன்பு ஒன்றாக இணைந்து வந்ததால், ஒரு அடையாளக் குறிப்பு ஒரு உணர்வைத் தூண்டலாம்"],[["ORDER",3,"keys",2,0],"பழக்கப்படுத்தல் (கண்டிஷனிங்)"],[["ORDER",3,"keys",2,1],"இடங்கள், மனிதர்கள், ஒலிகளோடு பயங்களும் ஆறுதல்களும் எப்படி இணைக்கப்படுகின்றன"],[["ORDER",3,"keys",3,0],"மீண்டும் இணைத்தல்"],[["ORDER",3,"keys",3,1],"அந்தக் குறிப்பைப் பாதுகாப்போடு இணைப்பது, போட்டியிடும் ஒரு புதிய இணைப்பை உருவாக்குகிறது"],[["ORDER",3,"tr",0],"பழைய உணர்வைத் தூண்டும் ஒரு குறிப்பைக் குறிப்பிடுங்கள்"],[["ORDER",3,"tr",1],"வேண்டுமென்றே அந்தக் குறிப்பை அமைதி தரும் ஒன்றோடு இணையுங்கள்"],[["ORDER",3,"tr",2],"பல முறை திரும்பச் செய்யுங்கள்"],[["ORDER",3,"rl"],"பாதுகாப்பான உறவுகள் நெருக்கத்தை ஆபத்தோடு அல்ல, அமைதியோடு “இணைக்கின்றன”."],[["ORDER",3,"simple"],"மூளை செல்கள் திரும்பத் திரும்ப ஒன்றாக வேலை செய்யும்போது, அவை நண்பர்களாகி வலுவாக இணைகின்றன. பழக்கங்கள் அப்படித்தான் உருவாகின்றன."],[["ORDER",4,"t"],"பயன்படுத்துங்கள், இல்லையென்றால் இழப்பீர்கள்: கத்தரித்தல்"],[["ORDER",4,"u"],"மூளை தான் பயன்படுத்தாத இணைப்புகளைக் கத்தரிக்கிறது. அதனால்தான் பயன்படுத்தாத திறன்கள் மங்குகின்றன; பழைய பழக்கங்களை விட்டு விலகும்போது அவை மெல்ல வலுவிழக்கின்றன."],[["ORDER",4,"steps",0],"பாதை பயன்படுத்தப்படுவதில்லை"],[["ORDER",4,"steps",1],"சமிக்ஞைகள் குறைகின்றன"],[["ORDER",4,"steps",2],"இணைப்பு வலுவிழக்கிறது"],[["ORDER",4,"steps",3],"கத்தரிக்கப்படுகிறது அல்லது அமைதியாகிறது"],[["ORDER",4,"steps",4],"பழைய வடிவம் தன் ஈர்ப்பை இழக்கிறது"],[["ORDER",4,"keys",0,0],"சினாப்ஸ் கத்தரித்தல்"],[["ORDER",4,"keys",0,1],"மூளையைத் திறமையாக்க, பலவீனமான அல்லது பயன்படாத இணைப்புகளை நீக்குதல்"],[["ORDER",4,"keys",1,0],"பதின்பருவம்"],[["ORDER",4,"keys",1,1],"பெரிய அளவில் கத்தரித்தல் நடக்கும் காலம்; அதனால்தான் பதின்வயது ஆண்டுகள் நம்மை அதிகம் உருவாக்குகின்றன"],[["ORDER",4,"keys",2,0],"அழிதல் (எக்ஸ்டிங்ஷன்)"],[["ORDER",4,"keys",2,1],"பழைய கற்றல் புதிய கற்றலால் அடக்கப்படுகிறது, அழிக்கப்படுவதில்லை; மன அழுத்தத்தில் அது திரும்பி வரலாம்"],[["ORDER",4,"keys",3,0],"தானாகத் திரும்புதல்"],[["ORDER",4,"keys",3,1],"பழைய பழக்கங்கள் ஏன் சில நேரம் திரும்பத் தோன்றுகின்றன, அது ஏன் இயல்பானது"],[["ORDER",4,"tr",0],"மன அழுத்தத்தில் பழைய பழக்கங்கள் திரும்பும் என்று, அவமான உணர்வு இல்லாமல் எதிர்பாருங்கள்"],[["ORDER",4,"tr",1],"பழையதோடு சண்டையிடுவதற்குப் பதிலாக, புதிய பாதைக்குத் தொடர்ந்து ஊட்டம் கொடுங்கள்"],[["ORDER",4,"rl"],"பின்னடைவுகள் தோல்விக்கான ஆதாரம் அல்ல; பழைய பாதை இன்னும் அங்கே இருக்கிறது என்பதே அவை."],[["ORDER",4,"simple"],"ஒரு தோட்டக்காரர் புதரை வெட்டி ஒழுங்குபடுத்துவது போல, நீங்கள் பயன்படுத்தாத பாதைகளை மூளை சுத்தம் செய்கிறது. நல்ல பாதைகளைத் தொடர்ந்து பயன்படுத்துங்கள்!"],[["ORDER",5,"t"],"மையலின்: பயிற்சி பாதைகளை வேகமாக்குகிறது"],[["ORDER",5,"u"],"மையலின் என்பது அடிக்கடி பயன்படுத்தப்படும் நரம்பு இழைகளைச் சுற்றியிருக்கும் காப்பு உறை; அது சமிக்ஞைகளை 100 மடங்கு வரை வேகமாக்குகிறது. திரும்பத் திரும்பச் செய்வது உண்மையில் சாலையையே மேம்படுத்துகிறது."],[["ORDER",5,"steps",0],"பாதை திரும்பத் திரும்பப் பயன்படுத்தப்படுகிறது"],[["ORDER",5,"steps",1],"மையலின் ஆக்சானைச் சுற்றிக்கொள்கிறது"],[["ORDER",5,"steps",2],"சமிக்ஞைகள் வேகமாகப் பயணிக்கின்றன"],[["ORDER",5,"steps",3],"திறன் தானாக நடப்பதுபோல் உணரப்படுகிறது"],[["ORDER",5,"steps",4],"குறைந்த முயற்சியே தேவை"],[["ORDER",5,"keys",0,0],"மையலின் உருவாதல்"],[["ORDER",5,"keys",0,1],"ஆக்சான்களுக்குக் காப்பு உறை இடுதல்; இது 25 வயதுகளின் நடுப்பகுதி வரையும் அதற்குப் பின்னும் தொடர்கிறது"],[["ORDER",5,"keys",1,0],"தானியங்கித் தன்மை"],[["ORDER",5,"keys",1,1],"ஒரு திறனுக்கு இனி நனவான முயற்சி தேவைப்படாத நிலை"],[["ORDER",5,"keys",2,0],"திட்டமிட்ட பயிற்சி"],[["ORDER",5,"keys",2,1],"இப்போதைய திறனுக்குச் சற்று மேலே, கவனத்தோடு, திரும்பத் திரும்பச் செய்யும் பயிற்சி"],[["ORDER",5,"keys",3,0],"தூக்கம்"],[["ORDER",5,"keys",3,1],"பயிற்சியை நீடித்த மாற்றமாக உறுதிப்படுத்துகிறது"],[["ORDER",5,"tr",0],"அமைதியாக இருக்கும்போதே ஒரு அமைதிப்படுத்தும் திறனைப் பயிற்சி செய்யுங்கள்; அப்போது மன அழுத்தம் வரும்போது அது தயாராக இருக்கும்"],[["ORDER",5,"tr",1],"எப்போதாவது செய்யும் நீண்ட பயிற்சியை விட, தினமும் செய்யும் சிறிய பயிற்சியே சிறந்தது"],[["ORDER",5,"rl"],"ஆவிக்குரிய ஒழுக்கங்களும் இதே அடிப்படையில் வேலை செய்கின்றன: திரும்பத் திரும்பச் செய்வது குணத்தை உருவாக்குகிறது."],[["ORDER",5,"simple"],"பயிற்சி உங்கள் மூளைப் பாதைகளுக்கு ஒரு சிறப்பு உறையைப் போடுகிறது; அது புதிய வழுவழுப்பான சாலை போல செய்திகளை வேகமாகச் செல்ல வைக்கிறது."],[["ORDER",6,"t"],"மூளை வரைபடம்: முக்கியப் பகுதிகள்"],[["ORDER",6,"u"],"உணர்வு, மன அழுத்தம், நினைவாற்றல், சுயக்கட்டுப்பாடு ஆகியவற்றில் அதிகம் ஈடுபடும் மூளைப் பகுதிகளுக்கான எளிய வழிகாட்டி."],[["ORDER",6,"steps",0],"மூளைத்தண்டு உங்களை உயிரோடு வைத்திருக்கிறது"],[["ORDER",6,"steps",1],"லிம்பிக் பகுதிகள் முக்கியமானவற்றைக் குறித்து வைக்கின்றன"],[["ORDER",6,"steps",2],"மூளைப் புறணி யோசிக்கிறது, திட்டமிடுகிறது, சிந்தித்துப் பார்க்கிறது"],[["ORDER",6,"steps",3],"பகுதிகள் வலைப்பின்னல்களாக எப்போதும் ஒன்றோடொன்று பேசுகின்றன"],[["ORDER",6,"keys",0,0],"முன்மூளைப் புறணி"],[["ORDER",6,"keys",0,1],"திட்டமிடுதல், தேர்வு செய்தல், உணர்வை அமைதிப்படுத்துதல், பிறர் உணர்வைப் புரிதல்"],[["ORDER",6,"keys",1,0],"அமிக்டாலா (பய எச்சரிக்கை மையம்)"],[["ORDER",6,"keys",1,1],"அச்சுறுத்தலையும் முக்கியத்துவத்தையும் கண்டறியும் கருவி; எச்சரிக்கை மணி"],[["ORDER",6,"keys",2,0],"ஹிப்போகேம்பஸ்"],[["ORDER",6,"keys",2,1],"சூழலும் நினைவும்: “எப்போது, எங்கே”"],[["ORDER",6,"keys",3,0],"இன்சுலா"],[["ORDER",6,"keys",3,1],"உடலின் சமிக்ஞைகளைப் படிக்கிறது; உள்ளுணர்வுகள்"],[["ORDER",6,"keys",4,0],"ஹைப்போதலாமஸ்"],[["ORDER",6,"keys",4,1],"ஹார்மோன் வழியான மன அழுத்தப் பதிலைத் தொடங்குகிறது"],[["ORDER",6,"keys",5,0],"முன்புற சிங்குலேட்"],[["ORDER",6,"keys",5,1],"முரண்பாட்டையும் வலியையும் கவனிக்கிறது, சமூக வலி உட்பட"],[["ORDER",6,"tr",0],"உங்களுக்குள் நடப்பதற்குப் பெயரிட இந்த வரைபடத்தைப் பயன்படுத்துங்கள் (“இப்போது என் எச்சரிக்கை மணி சத்தமாக அடிக்கிறது”)"],[["ORDER",6,"tr",1],"நினைவில் வையுங்கள்: மூளைப் பகுதிகள் தனித்தனிப் பெட்டிகளாக அல்ல, வலைப்பின்னல்களாக வேலை செய்கின்றன"],[["ORDER",6,"rl"],"நமக்குள் நடப்பதற்குப் பெயரிடுவது புரிந்துகொள்ளும் செயல், தீர்ப்பிடும் செயல் அல்ல."],[["ORDER",6,"simple"],"ஒரு வீட்டின் அறைகளைப் போல, மூளையின் வெவ்வேறு பகுதிகளுக்கு வெவ்வேறு வேலைகள் உண்டு: ஒரு எச்சரிக்கை மணி, ஒரு கேப்டன், ஒரு நூலகர், இன்னும் பல."],[["ORDER",7,"t"],"எச்சரிக்கை மணியும் விமானியும்: அமிக்டாலா & முன்மூளைப் புறணி"],[["ORDER",7,"u"],"ஆபத்து இருக்கக்கூடும் என்றால் அமிக்டாலா வேகமாகச் செயல்படுகிறது. முன்மூளைப் புறணி சிந்தித்து, காரணம் ஆராய்ந்து, எச்சரிக்கை மணியை அமைதிப்படுத்த முடியும்; ஆனால் அது இயங்கிக்கொண்டிருக்கும்போது மட்டுமே."],[["ORDER",7,"steps",0],"ஒரு குறிப்பு கண்டறியப்படுகிறது"],[["ORDER",7,"steps",1],"அமிக்டாலா எச்சரிக்கை (வேகமானது)"],[["ORDER",7,"steps",2],"உடல் செயலுக்குத் தயாராகிறது"],[["ORDER",7,"steps",3],"முன்மூளைப் புறணி உண்மைகளைச் சரிபார்க்கிறது (மெதுவானது)"],[["ORDER",7,"steps",4],"எச்சரிக்கை அமைதியாகிறது அல்லது அதிகரிக்கிறது"],[["ORDER",7,"keys",0,0],"தாழ்ந்த பாதை"],[["ORDER",7,"keys",0,1],"அமிக்டாலா வழியாக வேகமான, தோராயமான ஆபத்துக் கண்டறிதல்"],[["ORDER",7,"keys",1,0],"உயர்ந்த பாதை"],[["ORDER",7,"keys",1,1],"மூளைப் புறணி வழியாக மெதுவான, துல்லியமான மதிப்பீடு"],[["ORDER",7,"keys",2,0],"மேலிருந்து கீழான அமைதிப்படுத்துதல்"],[["ORDER",7,"keys",2,1],"மறுமதிப்பீடு செய்தும் பெயரிட்டும் முன்மூளைப் புறணி எச்சரிக்கையை அமைதிப்படுத்துதல்"],[["ORDER",7,"keys",3,0],"கீழிருந்து மேலான அமைதிப்படுத்துதல்"],[["ORDER",7,"keys",3,1],"முன்மூளைப் புறணி மீண்டும் இயங்கும்படி, உடலை அமைதிப்படுத்துதல் (மூச்சு, அசைவு)"],[["ORDER",7,"tr",0],"அடக்குவதற்குப் பெயரிடுங்கள்: “நான் ___ உணர்கிறேன்” என்று சொல்லுங்கள்"],[["ORDER",7,"tr",1],"எச்சரிக்கை மிகச் சத்தமாக இருக்கும்போது முதலில் உடலை அமைதிப்படுத்துங்கள்"],[["ORDER",7,"tr",2],"பிறகு உண்மைகளை யோசித்துப் பாருங்கள்"],[["ORDER",7,"rl"],"நம் அருகில் இருக்கும் அமைதியான, நம்பகமான ஒரு குரல், “விமானி” கட்டுப்பாட்டில் தொடர்ந்து இருக்க உதவுகிறது."],[["ORDER",7,"simple"],"உங்கள் மூளையில் ஒரு வேகமான புகை எச்சரிக்கை மணியும் ஒரு ஞானமுள்ள கேப்டனும் இருக்கிறார்கள். எச்சரிக்கை மணி முதலில் கத்துகிறது; அது உண்மையில் ஆபத்தா என்று கேப்டன் சரிபார்க்கிறார்."],[["ORDER",8,"t"],"மூடி திறந்துபோதல்: கை மாதிரி"],[["ORDER",8,"u"],"Dan Siegel அவர்களின் கை மாதிரி: கட்டைவிரலை உள்ளே மடக்கி, கையை முஷ்டியாக்குங்கள். கட்டைவிரல் உணர்வு மூளை; மற்ற விரல்கள் சிந்திக்கும் மூளை. மன அழுத்தத்தில் விரல்கள் மேலே தூக்கப்படுகின்றன: நம் “மூடி திறந்துபோகிறது”."],[["ORDER",8,"steps",0],"மன அழுத்தம் அதிகரிக்கிறது"],[["ORDER",8,"steps",1],"உணர்வு மூளை பற்றி எரிகிறது"],[["ORDER",8,"steps",2],"சிந்திக்கும் மூளை செயலிழக்கிறது"],[["ORDER",8,"steps",3],"உடனடி எதிர்வினை நடத்தை"],[["ORDER",8,"steps",4],"அமைதியாகுதல்"],[["ORDER",8,"steps",5],"மூடி மீண்டும் மூடுகிறது"],[["ORDER",8,"steps",6],"உறவைச் சரிசெய்தல்"],[["ORDER",8,"keys",0,0],"மணிக்கட்டு"],[["ORDER",8,"keys",0,1],"மூளைத்தண்டு: உயிர்வாழ்தல், விழிப்புநிலை"],[["ORDER",8,"keys",1,0],"கட்டைவிரல்"],[["ORDER",8,"keys",1,1],"லிம்பிக் பகுதி: உணர்வு, நினைவு, எச்சரிக்கை"],[["ORDER",8,"keys",2,0],"விரல்கள்"],[["ORDER",8,"keys",2,1],"மூளைப் புறணி, குறிப்பாக முன்மூளைப் புறணி: சிந்தித்தலும் தேர்வு செய்தலும்"],[["ORDER",8,"keys",3,0],"திறந்துபோன மூடி"],[["ORDER",8,"keys",3,1],"மூளைப் புறணி செயலிழந்து, எதிர்வினைகள் கட்டுப்பாட்டை எடுத்துக்கொள்ளும்போது"],[["ORDER",8,"tr",0],"உங்கள் மூடி திறந்துபோகத் தொடங்கும் ஆரம்ப அறிகுறிகளைக் கவனியுங்கள்"],[["ORDER",8,"tr",1],"பேசுவதற்கு முன் சற்று இடைவெளி எடுத்து உடலை அமைதிப்படுத்துங்கள்"],[["ORDER",8,"tr",2],"மூடி மீண்டும் மூடியதும் உறவைச் சரிசெய்யத் திரும்புங்கள்"],[["ORDER",8,"rl"],"“மூடி திறந்துபோன” பிறகு உறவைச் சரிசெய்வது, பிள்ளைகளுக்கும் வாழ்க்கைத் துணைக்கும் கிருபையைக் காட்டும் முன்மாதிரியாகிறது."],[["ORDER",8,"simple"],"கட்டைவிரலை உள்ளே வைத்து முஷ்டியாக்குங்கள். உங்கள் விரல்கள்தான் சிந்திக்கும் மூளை. நீங்கள் மிகவும் கலங்கும்போது, விரல்கள் மேலே தூக்கிக்கொள்ளும்; உங்களால் சரியாக யோசிக்க முடியாது. மூச்சு விடுவது அவற்றை மீண்டும் கீழே கொண்டுவருகிறது."],[["ORDER",9,"t"],"மன அழுத்தப் பதில்: HPA அச்சு (மன அழுத்த ஹார்மோன் சங்கிலி)"],[["ORDER",9,"u"],"மன அழுத்தம் தாக்கும்போது, ஹைப்போதலாமஸ் பிட்யூட்டரி சுரப்பிக்குச் சமிக்ஞை அனுப்புகிறது; அது அட்ரீனல் சுரப்பிகளுக்குச் சமிக்ஞை அனுப்பி கார்டிசோலை வெளியிடச் செய்கிறது. குறுகிய காலத்தில் இது உதவுகிறது; நீண்ட காலத்தில் உங்களைச் சோர்வடையச் செய்கிறது."],[["ORDER",9,"steps",0],"மன அழுத்தக் காரணி"],[["ORDER",9,"steps",1],"ஹைப்போதலாமஸ் (CRH)"],[["ORDER",9,"steps",2],"பிட்யூட்டரி சுரப்பி (ACTH)"],[["ORDER",9,"steps",3],"அட்ரீனல் சுரப்பிகள் கார்டிசோலை வெளியிடுகின்றன"],[["ORDER",9,"steps",4],"ஆற்றல் திரட்டப்படுகிறது"],[["ORDER",9,"steps",5],"பதிலை நிறுத்தும்படி கார்டிசோல் மூளைக்குச் சொல்கிறது"],[["ORDER",9,"keys",0,0],"தீவிர (குறுகிய கால) மன அழுத்தம்"],[["ORDER",9,"keys",0,1],"கவனத்தைக் கூர்மையாக்கக்கூடிய குறுகிய வெடிப்புகள்"],[["ORDER",9,"keys",1,0],"நாள்பட்ட மன அழுத்தம்"],[["ORDER",9,"keys",1,1],"நினைவாற்றல், தூக்கம், நோய் எதிர்ப்பு சக்தியைப் பாதிக்கும் தொடர்ச்சியான கார்டிசோல்"],[["ORDER",9,"keys",2,0],"அலோஸ்டாடிக் சுமை"],[["ORDER",9,"keys",2,1],"நீண்டகால மன அழுத்தத்தால் வரும் தேய்மானம்"],[["ORDER",9,"keys",3,0],"மீட்சி"],[["ORDER",9,"keys",3,1],"தூக்கம், அசைவு, உறவுத் தொடர்பு ஆகியவை அமைப்பை மீண்டும் சீராக்க உதவுகின்றன"],[["ORDER",9,"tr",0],"வார இறுதி ஓய்வுகள் மட்டும் அல்ல, தினமும் மீட்சித் தருணங்களை உருவாக்குங்கள்"],[["ORDER",9,"tr",1],"மன அழுத்த ஹார்மோன்களை எரித்துத் தீர்க்க உடலை அசையுங்கள்"],[["ORDER",9,"tr",2],"தூக்கத்தைப் பாதுகாத்துக்கொள்ளுங்கள்"],[["ORDER",9,"rl"],"வேலைக்கும் ஓய்வுக்குமான ஒழுங்கு நம் உடல்கள் இயங்கும் விதத்திலேயே கட்டமைக்கப்பட்டிருக்கிறது."],[["ORDER",9,"simple"],"நமக்கு மன அழுத்தம் வரும்போது, மூளை ஒரு சங்கிலி வழியாகச் செய்தி அனுப்பி மன அழுத்த வேதிப்பொருட்களை உருவாக்குகிறது. ஓய்வும் அமைதியும் அந்தச் சங்கிலியை நிறுத்துகின்றன."],[["ORDER",10,"t"],"நரம்பு மண்டல ஏணி (பாலிவேகல் வரைபடம்)"],[["ORDER",10,"u"],"மூன்று தன்னியக்க நரம்பு நிலைகளைக் காட்டும், சிகிச்சையில் பிரபலமான ஒரு வரைபடம்: பாதுகாப்பாகவும் பிறரோடு இணைந்தும் (மேலே), சண்டை அல்லது ஓட்டம் (நடுவில்), முடங்கிப்போதல் (கீழே). இதன் சில உடலியல் கூற்றுகள் விவாதத்துக்குரியவை, ஆனால் உங்கள் நிலையைக் கவனிக்க இந்த வரைபடம் பயனுள்ளது."],[["ORDER",10,"steps",0],"பாதுகாப்பாகவும் இணைந்தும்"],[["ORDER",10,"steps",1],"ஆபத்தை உணர்தல்"],[["ORDER",10,"steps",2],"செயலுக்குத் தயாராகுதல்: சண்டை அல்லது ஓட்டம்"],[["ORDER",10,"steps",3],"தாங்க முடியாவிட்டால்: முடங்கிப்போதல்"],[["ORDER",10,"steps",4],"பாதுகாப்பின் அடையாளங்கள்"],[["ORDER",10,"steps",5],"மீண்டும் மேலே ஏறுதல்"],[["ORDER",10,"keys",0,0],"வென்ட்ரல் (மேலே)"],[["ORDER",10,"keys",0,1],"அமைதி, ஆர்வம், இணைப்பு; பிறரோடு உறவாடுதல்"],[["ORDER",10,"keys",1,0],"சிம்பதெடிக் (நடுவில்)"],[["ORDER",10,"keys",1,1],"செயலுக்குத் தயார்; பதட்டம், கோபம், அமைதியின்மை"],[["ORDER",10,"keys",2,0],"டார்சல் (கீழே)"],[["ORDER",10,"keys",2,1],"சோர்ந்து விழுதல், மரத்துப்போதல், துண்டிக்கப்பட்ட உணர்வு"],[["ORDER",10,"keys",3,0],"நியூரோசெப்ஷன்"],[["ORDER",10,"keys",3,1],"பாதுகாப்பா ஆபத்தா என்று உடல் தானாகவே கவனித்துக்கொண்டிருப்பது"],[["ORDER",10,"tr",0],"கேளுங்கள்: “இப்போது நான் ஏணியில் எங்கே இருக்கிறேன்?”"],[["ORDER",10,"tr",1],"பாதுகாப்பின் அடையாளங்களைப் பயன்படுத்துங்கள் (கனிவான குரல், கண்ணோடு கண் பார்த்தல், மெதுவான மூச்சு)"],[["ORDER",10,"tr",2],"ஒரு நேரத்தில் ஒரு படியாக ஏறுங்கள்"],[["ORDER",10,"rl"],"பாதுகாப்பான முகங்களும் குரல்களும் வலிமையாக அமைதிப்படுத்துகின்றன: உறவின் வழியாக நாம் இணை-அமைதிப்படுத்தல் பெறுகிறோம்."],[["ORDER",10,"simple"],"ஒரு ஏணியை நினைத்துக்கொள்ளுங்கள்: உச்சியில் நீங்கள் பாதுகாப்பாகவும் நட்பாகவும் உணர்கிறீர்கள்; நடுவில் சண்டையிடவோ ஓடவோ தயாராக உணர்கிறீர்கள்; கீழே நீங்கள் முடங்கிப்போனதாக உணர்கிறீர்கள். அன்பான மனிதர்களும் மெதுவான மூச்சும் மீண்டும் மேலே ஏற உதவுகின்றன."],[["ORDER",11,"t"],"வெகுமதிச் சுழற்சி: டோபமைன் & பழக்கங்கள்"],[["ORDER",11,"u"],"டோபமைன் விருப்பத்தையும் கற்றலையும் இயக்குகிறது. ஒரு வெகுமதியை எதிர்பார்க்கும்போது அது அதிகரித்து, அந்த நடத்தையைத் திரும்பச் செய்யும்படி மூளைக்குக் கற்றுக்கொடுக்கிறது."],[["ORDER",11,"steps",0],"குறிப்பு"],[["ORDER",11,"steps",1],"டோபமைன் உயர்வு (விருப்பம்)"],[["ORDER",11,"steps",2],"செயல்"],[["ORDER",11,"steps",3],"வெகுமதி (அல்லது இல்லை)"],[["ORDER",11,"steps",4],"மூளை தன் கணிப்பைப் புதுப்பிக்கிறது"],[["ORDER",11,"steps",5],"பழக்கம் வலுப்படுகிறது"],[["ORDER",11,"keys",0,0],"டோபமைன்"],[["ORDER",11,"keys",0,1],"“இது தேடிப் போகத் தகுந்தது” என்று சமிக்ஞை கொடுக்கிறது; இது ரசிப்பதை விட விரும்புவதைப் பற்றியது"],[["ORDER",11,"keys",1,0],"கணிப்புப் பிழை"],[["ORDER",11,"keys",1,1],"எதிர்பாராத வெகுமதிகள் அதிகக் கற்றலை உருவாக்குகின்றன"],[["ORDER",11,"keys",2,0],"ஸ்ட்ரையேட்டம்"],[["ORDER",11,"keys",2,1],"பழக்கங்களையும் அன்றாட வழக்கங்களையும் சேமிக்கிறது"],[["ORDER",11,"keys",3,0],"சகிப்புத்தன்மை (டாலரன்ஸ்)"],[["ORDER",11,"keys",3,1],"அதே விளைவுக்கு அதிகத் தூண்டல் தேவைப்படுதல்"],[["ORDER",11,"tr",0],"எந்தக் குறிப்புகள் விருப்பத்தைத் தூண்டுகின்றன என்று கவனியுங்கள்"],[["ORDER",11,"tr",1],"புதிய ஆரோக்கியமான பழக்கங்களோடு சிறிய வெகுமதிகளைச் சேருங்கள்"],[["ORDER",11,"tr",2],"உடனடி வெகுமதி தரும் தூண்டுதல்கள் எளிதாகக் கைக்கு எட்டுவதைக் குறையுங்கள்"],[["ORDER",11,"rl"],"எளிய வரங்களில் (உணவு, இயற்கை, நட்பு) மகிழ்வது, நமக்கு எது வெகுமதியாகத் தோன்றுகிறது என்பதை மீண்டும் பழக்கப்படுத்துகிறது."],[["ORDER",11,"simple"],"டோபமைன் என்பது “அதை மறுபடியும் செய்!” என்று சொல்லும் ஒரு மூளை வேதிப்பொருள். அது நாம் கற்றுக்கொள்ள உதவுகிறது, ஆனால் உடனடி இன்பங்கள் அதை ஏமாற்றிவிடலாம்."],[["ORDER",12,"t"],"நினைவும் உணர்வும்: மறைமுக நினைவும் வெளிப்படை நினைவும்"],[["ORDER",12,"u"],"வெளிப்படை நினைவுகள் என்பவை நீங்கள் நினைவுகூரக்கூடிய உண்மைகளும் கதைகளும். மறைமுக நினைவுகள் என்பவை உங்களுக்கே தெரியாமல் இயங்கும் உணர்ந்த எதிர்வினைகளும் உடல் நினைவுகளும்."],[["ORDER",12,"steps",0],"அனுபவம்"],[["ORDER",12,"steps",1],"அமிக்டாலா உணர்வின் கனத்தைக் குறித்து வைக்கிறது"],[["ORDER",12,"steps",2],"ஹிப்போகேம்பஸ் சூழலைச் சேர்க்கிறது"],[["ORDER",12,"steps",3],"வெளிப்படை + மறைமுக நினைவாகச் சேமிக்கப்படுகிறது"],[["ORDER",12,"steps",4],"குறிப்பு அந்த உணர்வை மீண்டும் எழுப்புகிறது"],[["ORDER",12,"keys",0,0],"வெளிப்படை நினைவு"],[["ORDER",12,"keys",0,1],"“எனக்கு நினைவிருக்கிறது, அப்போது…”: இதற்கு ஹிப்போகேம்பஸ் தேவை"],[["ORDER",12,"keys",1,0],"மறைமுக நினைவு"],[["ORDER",12,"keys",1,1],"கதை இல்லாமல் இருக்கும் உணர்வுகள், உடல் எதிர்வினைகள், எதிர்பார்ப்புகள்"],[["ORDER",12,"keys",2,0],"மன அழுத்தத்தின் கீழ்"],[["ORDER",12,"keys",2,1],"ஹிப்போகேம்பஸ் சரியாக வேலை செய்வதில்லை; அதனால் நினைவுகள் துண்டுதுண்டாக இருக்கலாம்"],[["ORDER",12,"keys",3,0],"ஒருங்கிணைப்பு"],[["ORDER",12,"keys",3,1],"உணர்ந்த நினைவைக் கதையோடு இணைப்பது, கடந்ததைக் கடந்ததாகவே உணர உதவுகிறது"],[["ORDER",12,"tr",0],"ஒரு எதிர்வினை அளவுக்கு மீறியதாகத் தோன்றும்போது, “இது எவ்வளவு பழைய உணர்வுபோல் இருக்கிறது?” என்று கேளுங்கள்"],[["ORDER",12,"tr",1],"தெளிவான தொடக்கம், நடு, முடிவு கொண்ட கதையாக அதை எழுதுங்கள்"],[["ORDER",12,"rl"],"கேட்கும் ஒருவரிடம் நம் கதையைச் சொல்வது, நினைவு ஒருங்கிணைய உதவுகிறது."],[["ORDER",12,"simple"],"சில நினைவுகளை நாம் கதைகளாகச் சொல்ல முடியும். மற்றவை வார்த்தைகள் இல்லாமல் உடல் நினைவில் வைத்திருக்கும் உணர்வுகள்."],[["ORDER",13,"t"],"நினைவு மறுஉறுதிப்படுத்தல்: பழைய கற்றலைப் புதுப்பித்தல்"],[["ORDER",13,"u"],"ஒரு பழைய உணர்வு நினைவு எழுப்பப்பட்டு, அதற்கு முரணான ஒரு அனுபவத்தைச் சந்திக்கும்போது, மூளை அதை வெறுமனே மேலெழுதுவதில்லை; அந்த அசல் கற்றலையே புதுப்பிக்க முடியும்."],[["ORDER",13,"steps",0],"பழைய உணர்வுக் கற்றல் எழுப்பப்படுகிறது"],[["ORDER",13,"steps",1],"புதிய அனுபவம் அதற்கு முரண்படுகிறது"],[["ORDER",13,"steps",2],"நினைவு சிறிது நேரம் மாற்றக்கூடியதாகிறது"],[["ORDER",13,"steps",3],"புதுப்பிக்கப்பட்ட கற்றல் சேமிக்கப்படுகிறது"],[["ORDER",13,"steps",4],"பழைய தூண்டுதல் தன் வலிமையை இழக்கிறது"],[["ORDER",13,"keys",0,0],"மறுஉறுதிப்படுத்தல்"],[["ORDER",13,"keys",0,1],"ஒரு நினைவு மீண்டும் எழுப்பப்பட்ட பிறகு அதை மறுபடி சேமித்தல்"],[["ORDER",13,"keys",1,0],"முரண்பாடு"],[["ORDER",13,"keys",1,1],"புதிய அனுபவம் பழைய எதிர்பார்ப்புக்குத் தெளிவாக முரணாக இருக்க வேண்டும்"],[["ORDER",13,"keys",2,0],"சாளரம் (வாய்ப்புக் காலம்)"],[["ORDER",13,"keys",2,1],"நினைவு எழுப்பப்பட்ட பின் சில மணி நேரக் காலம்"],[["ORDER",13,"keys",3,0],"உணரப்படும் மாற்றம்"],[["ORDER",13,"keys",3,1],"கஷ்டப்பட்டு சமாளிக்காமலேயே எதிர்வினை குறைதல்"],[["ORDER",13,"tr",0],"பழைய நம்பிக்கையை உணர்ந்தபடியே அதை நினைவுகூருங்கள்"],[["ORDER",13,"tr",1],"பிறகு அதற்குத் தெளிவாக முரணான ஒரு அனுபவத்தை மனதில் வைத்திருங்கள்"],[["ORDER",13,"tr",2],"ஆழமான வேலைக்கு ஒரு சிகிச்சையாளரோடு சேர்ந்து திரும்பச் செய்யுங்கள்"],[["ORDER",13,"rl"],"நிராகரிப்பை எதிர்பார்த்த இடத்திலேயே ஏற்றுக்கொள்ளப்படுவதை அனுபவிப்பது, பழைய எதிர்பார்ப்புகளை மாற்றி எழுதக்கூடும்."],[["ORDER",13,"simple"],"பழைய காயங்களைப் புதுப்பிக்க முடியும். பாதுகாப்பாகவும் நேசிக்கப்பட்டவர்களாகவும் உணரும்போது அவற்றை நினைத்தால், அவை குறைவாகவே வலிக்கும்."],[["ORDER",14,"t"],"இயல்புநிலை வலைப்பின்னலும் (DMN) திரும்பத் திரும்ப அசைபோடுதலும்"],[["ORDER",14,"u"],"மனம் ஒரு வேலையில் கவனம் செலுத்தாதபோது, இயல்புநிலை வலைப்பின்னல் (default mode network) இயங்குகிறது: பகல் கனவு, தன்னைப் பற்றிச் சிந்தித்தல், அடிக்கடி திரும்பத் திரும்ப அசைபோடுதல்."],[["ORDER",14,"steps",0],"மனம் ஓய்வில்"],[["ORDER",14,"steps",1],"DMN இயங்குகிறது"],[["ORDER",14,"steps",2],"தன்னை மையமாகக் கொண்ட சிந்தனை"],[["ORDER",14,"steps",3],"எதிர்மறைச் சுழற்சி (அசைபோடுதல்)"],[["ORDER",14,"steps",4],"மனநிலை தாழ்கிறது"],[["ORDER",14,"steps",5],"DMN இன்னும் அதிகமாக இயங்குகிறது"],[["ORDER",14,"keys",0,0],"DMN"],[["ORDER",14,"keys",0,1],"மனம் அலைபாயும்போதும் தன்னைப் பற்றிச் சிந்திக்கும்போதும் இயங்கும் வலைப்பின்னல்"],[["ORDER",14,"keys",1,0],"அசைபோடுதல்"],[["ORDER",14,"keys",1,1],"அதிகமாக இயங்கும் DMN-உடன் தொடர்புடைய, தன்னைப் பற்றிய திரும்பத் திரும்ப வரும் எதிர்மறைச் சிந்தனை"],[["ORDER",14,"keys",2,0],"பணி-சார்ந்த வலைப்பின்னல்"],[["ORDER",14,"keys",2,1],"கூர்ந்த கவனத்தால் இயங்குகிறது; அது DMN-ஐ அமைதிப்படுத்துகிறது"],[["ORDER",14,"keys",3,0],"மன விழிப்புணர்வு (மைண்ட்ஃபுல்னஸ்)"],[["ORDER",14,"keys",3,1],"DMN செயல்பாட்டைச் சிறப்பாகக் கட்டுப்படுத்துவதோடு தொடர்புடையது"],[["ORDER",14,"tr",0],"மனம் அலைபாய்வதைக் கவனித்து, மெதுவாக இந்தத் தருணத்துக்குத் திரும்புங்கள்"],[["ORDER",14,"tr",1],"கைகளையோ புலன்களையோ ஈடுபடுத்துங்கள் (நடத்தல், சமைத்தல், தோட்ட வேலை)"],[["ORDER",14,"tr",2],"சிறிது நேரம் கவனமான விழிப்புணர்வைப் பயிற்சி செய்யுங்கள்"],[["ORDER",14,"rl"],"தியான ஜெபமும் கவனப் பயிற்சிகளும் அலைபாயும் மனதை இந்தத் தருணத்தில் நிலைத்திருக்கப் பழக்குகின்றன."],[["ORDER",14,"simple"],"நாம் எதுவும் செய்யாமல் இருக்கும்போது, நம் மனம் அலைபாய்ந்து சில நேரம் கவலைப்படுகிறது. கவனத்தோடு ஏதாவது செய்வது அதை அமைதிப்படுத்த உதவுகிறது."],[["ORDER",15,"t"],"உள்ளுணர்தல்: இன்சுலாவும் உடலின் சமிக்ஞைகளும்"],[["ORDER",15,"u"],"உள்ளுணர்தல் (இன்டரோசெப்ஷன்) என்பது உங்கள் உடலுக்குள் நடப்பதை உணர்வது: இதயத் துடிப்பு, மூச்சு, பசி, இறுக்கம். இன்சுலா இந்தச் சமிக்ஞைகளை வரைபடமாக்கி அவற்றை உணர்வோடு இணைக்கிறது."],[["ORDER",15,"steps",0],"உடல் சமிக்ஞைகளை அனுப்புகிறது"],[["ORDER",15,"steps",1],"இன்சுலா அவற்றை வரைபடமாக்குகிறது"],[["ORDER",15,"steps",2],"அவற்றின் அர்த்தத்தை மூளை கணிக்கிறது"],[["ORDER",15,"steps",3],"உணர்வு உருவாக்கப்படுகிறது"],[["ORDER",15,"steps",4],"செயல்"],[["ORDER",15,"keys",0,0],"உள்ளுணர்தல்"],[["ORDER",15,"keys",0,1],"உடலின் உள் நிலைகளை உணர்தல்"],[["ORDER",15,"keys",1,0],"இன்சுலா"],[["ORDER",15,"keys",1,1],"உடலின் சமிக்ஞைகளை உணர்வோடும் விழிப்புணர்வோடும் ஒருங்கிணைக்கிறது"],[["ORDER",15,"keys",2,0],"உடல் பட்ஜெட்"],[["ORDER",15,"keys",2,1],"ஆற்றலையும் வளங்களையும் மூளை நிர்வகிக்கும் விதம்"],[["ORDER",15,"keys",3,0],"உணர்வு நுணுக்கம்"],[["ORDER",15,"keys",3,1],"உணர்வுகளுக்கு நுணுக்கமான வார்த்தைகள் இருந்தால், சிறப்பாக அமைதிப்படுத்த முடிகிறது"],[["ORDER",15,"tr",0],"2 நிமிட உடல் ஸ்கேன் செய்யுங்கள்"],[["ORDER",15,"tr",1],"உணர்வுகளுக்கு முன் உடல் உணர்ச்சிகளுக்குப் பெயரிடுங்கள்"],[["ORDER",15,"tr",2],"இன்னும் குறிப்பான உணர்வு வார்த்தைகளைக் கற்றுக்கொள்ளுங்கள்"],[["ORDER",15,"rl"],"உடலைக் கவனிப்பது, அதை முழு மனிதனின் ஒரு பகுதியாகக் கனம்பண்ணுகிறது."],[["ORDER",15,"simple"],"நீங்கள் எப்படி உணர்கிறீர்கள் என்று சொல்ல, உங்கள் மூளை உங்கள் இதயத் துடிப்பு, வயிறு போன்ற உள்ளே நடப்பவற்றைக் கேட்கிறது."],[["ORDER",16,"t"],"படிப்படியாக மாற்றியமைத்தல்"],[["ORDER",16,"u"],"ஒரு வடிவத்தை மாற்ற ஒரு நடைமுறைச் சுழற்சி: கவனியுங்கள், பெயரிடுங்கள், நிறுத்துங்கள், தேர்ந்தெடுங்கள், திரும்பச் செய்யுங்கள், தூக்கம் அதை உறுதிப்படுத்தட்டும்."],[["ORDER",16,"steps",0],"பழைய வடிவத்தைக் கவனியுங்கள்"],[["ORDER",16,"steps",1],"அதற்குப் பெயரிடுங்கள் (“இதோ விமர்சகர் வந்துவிட்டார்”)"],[["ORDER",16,"steps",2],"நிறுத்தி மூச்சு விடுங்கள்"],[["ORDER",16,"steps",3],"புதிய பதில்செயலைத் தேர்ந்தெடுங்கள்"],[["ORDER",16,"steps",4],"பல முறை திரும்பச் செய்யுங்கள்"],[["ORDER",16,"steps",5],"தூக்கம் உறுதிப்படுத்துகிறது"],[["ORDER",16,"steps",6],"புதிய இயல்புநிலை"],[["ORDER",16,"keys",0,0],"விழிப்புணர்வு"],[["ORDER",16,"keys",0,1],"நீங்கள் கவனிக்காததை உங்களால் மாற்ற முடியாது"],[["ORDER",16,"keys",1,0],"பெயரிடுதல்"],[["ORDER",16,"keys",1,1],"பெயரிடுவது முன்மூளைப் புறணியை இயக்குகிறது"],[["ORDER",16,"keys",2,0],"தேர்வுப் புள்ளி"],[["ORDER",16,"keys",2,1],"நிறுத்தும் அந்த இடைவெளியில்தான் மாற்றியமைத்தல் நடக்கிறது"],[["ORDER",16,"keys",3,0],"திரும்பத் திரும்பச் செய்தல்"],[["ORDER",16,"keys",3,1],"நூற்றுக்கணக்கான சிறிய முறைகள் புதிய பாதையைக் கட்டுகின்றன"],[["ORDER",16,"tr",0],"இந்த மாதம் மாற்றியமைக்க ஒரு வடிவத்தைத் தேர்ந்தெடுங்கள்"],[["ORDER",16,"tr",1],"அதைக் கவனிக்கும் ஒவ்வொரு முறையும் குறித்து வையுங்கள் (கவனிப்பதும் கணக்கில் சேரும்!)"],[["ORDER",16,"tr",2],"பரிபூரணத்தை அல்ல, திரும்பச் செய்யும் முறைகளைக் கொண்டாடுங்கள்"],[["ORDER",16,"rl"],"மறுரூபமாதல் பொதுவாகப் படிப்படியாகவே நடக்கிறது: “மகிமையின்மேல் மகிமையடைந்து.”"],[["ORDER",16,"simple"],"ஒரு பழக்கத்தை மாற்ற: அதைக் கவனியுங்கள், பெயரிடுங்கள், நிறுத்துங்கள், சிறந்த ஒன்றைத் தேர்ந்தெடுங்கள், பயிற்சி செய்யுங்கள். மறுபடியும் மறுபடியும்."],[["ORDER",17,"t"],"தூக்கம், அசைவு & மாற்றியமைக்கப்படும் மூளை"],[["ORDER",17,"u"],"வாழ்க்கை முறை நரம்பியல் நெகிழ்வுக்குத் துணை நிற்கிறது: தூக்கம் கற்றலை உறுதிப்படுத்துகிறது, உடற்பயிற்சி வளர்ச்சிக் காரணிகளை அதிகரிக்கிறது, உணவும் உறவுத் தொடர்பும் மூளைக்கு எரிபொருளாகின்றன."],[["ORDER",17,"steps",0],"கற்றுக்கொள்ளுங்கள் அல்லது பயிற்சி செய்யுங்கள்"],[["ORDER",17,"steps",1],"தூக்கம் உறுதிப்படுத்துகிறது"],[["ORDER",17,"steps",2],"உடற்பயிற்சி BDNF-ஐ அதிகரிக்கிறது"],[["ORDER",17,"steps",3],"உறவுத் தொடர்பு மன அழுத்தத்தைக் குறைக்கிறது"],[["ORDER",17,"steps",4],"மூளை மாறுவதற்கு இன்னும் தயாராகிறது"],[["ORDER",17,"keys",0,0],"BDNF"],[["ORDER",17,"keys",0,1],"மூளையிலிருந்து உருவாகும் நரம்பு வளர்ச்சிக் காரணி (Brain-derived neurotrophic factor): நியூரான்களுக்கான “உரம்”"],[["ORDER",17,"keys",1,0],"தூக்கம்"],[["ORDER",17,"keys",1,1],"ஆழ்ந்த தூக்கம் கற்றதை மீண்டும் ஓட்டிப் பார்த்துச் சேமிக்கிறது"],[["ORDER",17,"keys",2,0],"ஏரோபிக் உடற்பயிற்சி"],[["ORDER",17,"keys",2,1],"BDNF-ஐ அதிகரித்து ஹிப்போகேம்பஸுக்குத் துணை நிற்கிறது"],[["ORDER",17,"keys",3,0],"சமூக உறவுத் தொடர்பு"],[["ORDER",17,"keys",3,1],"மன அழுத்தத்தைத் தணித்து நல்வாழ்வுக்குத் துணை நிற்கிறது"],[["ORDER",17,"tr",0],"7–9 மணி நேரத் தூக்கத்தைப் பாதுகாத்துக்கொள்ளுங்கள்"],[["ORDER",17,"tr",1],"பெரும்பாலான நாட்களில் 20–30 நிமிடங்கள் உடலை அசையுங்கள்"],[["ORDER",17,"tr",2],"தூங்குவதற்கு முன் புதிய திறன்களைப் பயிற்சி செய்யுங்கள்"],[["ORDER",17,"rl"],"உடலைக் கவனித்துக்கொள்வது மனதைக் கவனித்துக்கொள்வதின் ஒரு பகுதி."],[["ORDER",17,"simple"],"தூக்கமும் உடற்பயிற்சியும் உங்கள் மூளை வளரவும் கற்கவும் உதவுகின்றன. அவை உங்கள் மூளைக்கு உணவு போன்றவை."],[["ORDER",18,"t"],"இணை-அமைதிப்படுத்தல்: மூளைகள் மூளைகளை அமைதிப்படுத்துகின்றன"],[["ORDER",18,"u"],"நரம்பு மண்டலங்கள் ஒன்றையொன்று அமைதிப்படுத்துகின்றன. அமைதியான ஒருவரின் குரல், முகம், உடனிருப்பு மற்றொருவரின் நரம்பு மண்டலம் அமைதியடைய உதவலாம். குழந்தைகள் தங்களைத் தாங்களே அமைதிப்படுத்தக் கற்றுக்கொள்வது இப்படித்தான்."],[["ORDER",18,"steps",0],"துயரம்"],[["ORDER",18,"steps",1],"இணைப்பைத் தேடிக் கை நீட்டுதல்"],[["ORDER",18,"steps",2],"அமைதியான உடனிருப்பு வழங்கப்படுகிறது"],[["ORDER",18,"steps",3],"நரம்பு மண்டலம் அமைதியடைகிறது"],[["ORDER",18,"steps",4],"காலப்போக்கில் சுய-அமைதிப்படுத்தல் கற்றுக்கொள்ளப்படுகிறது"],[["ORDER",18,"keys",0,0],"இணை-அமைதிப்படுத்தல்"],[["ORDER",18,"keys",0,1],"அமைதியாக இருக்கும் இன்னொருவரோடு இணைவதன் மூலம் அமைதியடைதல்"],[["ORDER",18,"keys",1,0],"இசைந்துணர்தல்"],[["ORDER",18,"keys",1,1],"இன்னொருவரின் நிலையைக் கவனித்து அதற்கு ஏற்பப் பதிலளித்தல்"],[["ORDER",18,"keys",2,0],"சுய-அமைதிப்படுத்தல்"],[["ORDER",18,"keys",2,1],"இணை-அமைதிப்படுத்தலின் பல அனுபவங்களால் உருவாகிறது"],[["ORDER",18,"keys",3,0],"உறவு முறிவும் உறவைச் சரிசெய்தலும்"],[["ORDER",18,"keys",3,1],"சிறிய முறிவுகளுக்குப் பின் வரும் மறு இணைப்பு மனவலிமையை உருவாக்குகிறது"],[["ORDER",18,"tr",0],"யார் உங்களை அமைதியாக உணர வைக்கிறார்கள் என்று கவனியுங்கள்"],[["ORDER",18,"tr",1],"துயரத்தில் இருக்கும் ஒருவருக்கு மெதுவான குரலையும் கனிவான பார்வையையும் கொடுங்கள்"],[["ORDER",18,"tr",2],"சண்டைக்குப் பிறகு உறவைச் சரிசெய்வதைப் பயிற்சி செய்யுங்கள்"],[["ORDER",18,"rl"],"உறவில்தான் நாம் சுகமடைகிறோம்: “ஒருவர் பாரத்தை ஒருவர் சுமந்து.”"],[["ORDER",18,"simple"],"அமைதியான ஒருவர் அருகில் இருக்கும்போது, நம் மூளையும் அமைதியாகிறது."],[["ORDER",19,"t"],"கவன வலைப்பின்னல்கள்"],[["ORDER",19,"u"],"கவனம் என்பது ஒரே விஷயம் அல்ல. மூன்று வலைப்பின்னல்கள் உங்களை விழிப்பாக்குகின்றன, திசைப்படுத்துகின்றன, வேலையில் நிலைத்திருக்கச் செய்கின்றன; நீங்கள் அலைபாயும்போது இயல்புநிலை வலைப்பின்னல் பொறுப்பேற்கிறது."],[["ORDER",19,"steps",0],"விழிப்பூட்டல்: தயாராகுதல்"],[["ORDER",19,"steps",1],"திசைப்படுத்தல்: எதில் கவனம் செலுத்துவது என்று தேர்ந்தெடுத்தல்"],[["ORDER",19,"steps",2],"செயல் கட்டுப்பாடு: வேலையில் நிலைத்திருத்தல், கவனச்சிதறல்களைப் புறக்கணித்தல்"],[["ORDER",19,"steps",3],"மனம் அலைபாய்கிறது: இயல்புநிலை வலைப்பின்னல் திரும்புகிறது"],[["ORDER",19,"steps",4],"கவனித்து, கவனத்தைத் திரும்பக் கொண்டுவாருங்கள்"],[["ORDER",19,"keys",0,0],"விழிப்பூட்டல்"],[["ORDER",19,"keys",0,1],"மூளைத்தண்டிலிருந்து வரும் நோராட்ரினலினால் இயக்கப்படும் தயார்நிலை"],[["ORDER",19,"keys",1,0],"திசைப்படுத்தல்"],[["ORDER",19,"keys",1,1],"கவனத்தை எங்கே திருப்புவது என்று தேர்ந்தெடுத்தல் (பெரைட்டல் பகுதிகள்)"],[["ORDER",19,"keys",2,0],"செயல் கட்டுப்பாடு"],[["ORDER",19,"keys",2,1],"இலக்குகளைப் பிடித்துக்கொண்டு கவனச்சிதறலை எதிர்த்தல் (முன்மூளைப் புறணியும் ACC-யும்)"],[["ORDER",19,"keys",3,0],"மீண்டும் கவனம் செலுத்துதல்"],[["ORDER",19,"keys",3,1],"அலைபாய்வதைக் கவனித்துத் திரும்பும் ஒவ்வொரு முறையும், அந்த வலைப்பின்னலைப் பயிற்றுவிக்கிறீர்கள்"],[["ORDER",19,"tr",0],"கவனம் திரும்பும் ஒவ்வொரு முறையையும் தோல்வியாக அல்ல, ஒரு பயிற்சிச் சுற்றாகக் கருதுங்கள்"],[["ORDER",19,"tr",1],"கவனத்தை இழுக்கும் குறிப்புகளைக் குறையுங்கள் (அறிவிப்புகள், திறந்திருக்கும் டேப்கள்)"],[["ORDER",19,"tr",2],"தினமும் சிறிது நேர மன விழிப்புணர்வுப் பயிற்சியால் கவனத்தைப் பழக்குங்கள்"],[["ORDER",19,"rl"],"கவனம் என்பது நடைமுறையில் அன்பு: நாம் எதைக் கவனிக்கிறோமோ அதுவே நாம் யாராக ஆகிறோம் என்பதை உருவாக்குகிறது."],[["ORDER",19,"simple"],"உங்கள் மூளையில் கவனத்துக்கு உதவியாளர்கள் இருக்கிறார்கள்: ஒருவர் உங்களை எழுப்புகிறார், ஒருவர் சுட்டிக்காட்டுகிறார், ஒருவர் உங்களைக் கவனத்தோடு வைத்திருக்கிறார்."],[["ORDER",20,"t"],"விழிப்புநிலை, கவனம் & ஈடுபாட்டின் (ஃப்ளோ) வேதியியல்"],[["ORDER",20,"u"],"செயல்திறன் ஒரு தலைகீழ் U வடிவத்தைப் பின்பற்றுகிறது: விழிப்புநிலை மிகக் குறைவாக இருந்தால் மந்தமாக இருக்கும், மிக அதிகமாக இருந்தால் பதறிப்போவோம். நோராட்ரினலின், டோபமைன், அசிட்டைல்கோலின் ஆகியவை “சரியான அளவு” கவன மண்டலத்தைச் சீராக்குகின்றன; அங்கேதான் முழு ஈடுபாடு (ஃப்ளோ) சாத்தியமாகிறது."],[["ORDER",20,"steps",0],"குறைந்த விழிப்புநிலை: மந்தம், சலிப்பு"],[["ORDER",20,"steps",1],"உயரும் விழிப்புநிலை: விழிப்பும் ஈடுபாடும்"],[["ORDER",20,"steps",2],"சிறந்த மண்டலம்: கவனம், முழு ஈடுபாடு சாத்தியம்"],[["ORDER",20,"steps",3],"மிக அதிகம்: பதட்டம், சிதறிய மனம்"],[["ORDER",20,"steps",4],"மீண்டு, மீண்டும் சீராகுங்கள்"],[["ORDER",20,"keys",0,0],"நோராட்ரினலின்"],[["ORDER",20,"keys",0,1],"மூளைத்தண்டிலிருந்து (லோகஸ் சீருலியஸ்) வரும் விழிப்பும் அவசர உணர்வும்"],[["ORDER",20,"keys",1,0],"டோபமைன்"],[["ORDER",20,"keys",1,1],"ஊக்கம், விருப்பம், முன்னேற்றத்தால் கிடைக்கும் வெகுமதி"],[["ORDER",20,"keys",2,0],"அசிட்டைல்கோலின்"],[["ORDER",20,"keys",2,1],"நுணுக்கங்களில் கவனத்தைக் கூர்மையாக்குகிறது"],[["ORDER",20,"keys",3,0],"தலைகீழ் U"],[["ORDER",20,"keys",3,1],"Yerkes–Dodson வடிவம்: சிக்கலான வேலைகளுக்கு மிதமான விழிப்புநிலையே சிறந்தது"],[["ORDER",20,"tr",0],"மந்தமாக இருந்தால், விழிப்புநிலையை உயர்த்துங்கள் (அசையுங்கள், வெளிச்சம், குளிர்ந்த தண்ணீர்)"],[["ORDER",20,"tr",1],"பதறிப்போனால், அதைக் குறையுங்கள் (மெதுவாக மூச்சை வெளியே விடுதல், ஒரே ஒரு வேலை)"],[["ORDER",20,"tr",2],"தொடர்ந்து செல்ல டோபமைனுக்கு ஒரு காரணம் கொடுக்க, சிறிய வெற்றிகளைப் பயன்படுத்துங்கள்"],[["ORDER",20,"rl"],"வேலையிலேயே கிடைக்கும் மகிழ்ச்சி நீடித்து நிற்கும் எரிபொருள்."],[["ORDER",20,"simple"],"நன்றாகக் கவனம் செலுத்த, நாம் அதிகத் தூக்கக் கலக்கத்திலும் இருக்கக்கூடாது, அதிகப் பரபரப்பிலும் இருக்கக்கூடாது; சரியான அளவில் இருக்க வேண்டும்."],[["ORDER",21,"t"],"மூளை தன் நிலையை எப்படி மாற்றுகிறது"],[["ORDER",21,"u"],"மூளைத்தண்டின் விழிப்புநிலை அமைப்புகள், ஹார்மோன்கள், உடலின் பின்னூட்டம் ஆகியவற்றைப் பயன்படுத்தி, உங்கள் மூளை தொடர்ந்து வெவ்வேறு நிலைகளுக்கு மாறுகிறது (விழிப்பு, அமைதி, தூக்கக் கலக்கம், அச்சுறுத்தல், கவனம்). நீங்கள் நேரடியாகக் கட்டுப்படுத்தக்கூடிய சில வழிகளில் மூச்சும் ஒன்று."],[["ORDER",21,"steps",0],"உள்ளீடு (எண்ணம், குறிப்பு, உடல் சமிக்ஞை)"],[["ORDER",21,"steps",1],"மூளைத்தண்டும் ஹைப்போதலாமஸும் விழிப்புநிலையைச் சரிசெய்கின்றன"],[["ORDER",21,"steps",2],"இதயம், மூச்சு, ஹார்மோன்கள் மாறுகின்றன"],[["ORDER",21,"steps",3],"இன்சுலா உடலைப் படிக்கிறது"],[["ORDER",21,"steps",4],"மூளை உங்கள் நிலையைப் புதுப்பிக்கிறது"],[["ORDER",21,"keys",0,0],"கீழிருந்து மேல்"],[["ORDER",21,"keys",0,1],"மனதை மாற்ற உடலை மாற்றுங்கள் (மூச்சு, அசைவு, வெப்பநிலை)"],[["ORDER",21,"keys",1,0],"மேலிருந்து கீழ்"],[["ORDER",21,"keys",1,1],"உடலை மாற்ற கவனத்தையும் அர்த்தத்தையும் மாற்றுங்கள்"],[["ORDER",21,"keys",2,0],"மூச்சை வெளியே விடுதல்"],[["ORDER",21,"keys",2,1],"நீண்ட வெளிமூச்சுகள் வேகஸ் நரம்பு வழியாக இதயத் துடிப்பைக் குறைக்கின்றன"],[["ORDER",21,"keys",3,0],"நிலை சார்ந்த கற்றல்"],[["ORDER",21,"keys",3,1],"எந்த நிலையில் ஒன்றைப் பயன்படுத்த வேண்டுமோ, அந்த நிலையில்தான் அதைச் சிறப்பாகக் கற்றுக்கொள்கிறோம்"],[["ORDER",21,"tr",0],"கீழிருந்து மேல் கருவி ஒன்றையும், மேலிருந்து கீழ் கருவி ஒன்றையும் சேர்த்துப் பயன்படுத்துங்கள்"],[["ORDER",21,"tr",1],"அமைதியாக இருக்கும்போதே அமைதிப்படுத்தும் கருவிகளைப் பயிற்சி செய்யுங்கள்; அப்போது மன அழுத்தத்திலும் அவை வேலை செய்யும்"],[["ORDER",21,"rl"],"ஜெபம், பாடல், மௌனம் ஆகியவற்றின் ஒழுங்கு நம் நிலையை ஒன்றாகச் சேர்ந்து மாற்றுகிறது."],[["ORDER",21,"simple"],"உங்கள் மூளை தூக்கக் கலக்கம், அமைதி, விழிப்பு, பயம் ஆகிய நிலைகளுக்கு இடையே மாறுகிறது. மூச்சு விடுவதும் அசைவதும் உங்கள் நிலையை மாற்ற உதவுகின்றன."],[["ORDER",22,"t"],"அதிர்ச்சிக் காயமும் (ட்ராமா) வளரும் மூளையும்"],[["ORDER",22,"u"],"குழந்தைப் பருவத்தில் தொடரும் மன அழுத்தம், மூளையை உயிர்பிழைப்புக்காகச் சீரமைக்கலாம்: அதிகமாக எதிர்வினையாற்றும் எச்சரிக்கை அமைப்பு, அணையாமல் இருக்கும் மன அழுத்த அமைப்பு, தன்னைத் துண்டித்துக்கொள்ளுதல் (டிஸ்ஸோசியேஷன்) போன்ற உத்திகள். மூளை தொடர்ந்து மாறக்கூடியதாக இருப்பதால், பாதுகாப்பான உறவுகளும் பயிற்சியும் அதை மீண்டும் சீரமைக்க உதவுகின்றன."],[["ORDER",22,"steps",0],"போதுமான ஆதரவு இல்லாமல் குழந்தைப் பருவத்தில் அச்சுறுத்தல்"],[["ORDER",22,"steps",1],"எச்சரிக்கை அமைப்பு அதிக உணர்திறன் பெறுகிறது"],[["ORDER",22,"steps",2],"மன அழுத்த ஹார்மோன்கள் அடிக்கடி அதிகமாக இருக்கின்றன"],[["ORDER",22,"steps",3],"உயிர்பிழைப்பு உத்திகள் கற்றுக்கொள்ளப்படுகின்றன"],[["ORDER",22,"steps",4],"பெரியவரான பின்: பாதுகாப்பு + பயிற்சி + உறவு"],[["ORDER",22,"steps",5],"படிப்படியான மறுசீரமைப்பு"],[["ORDER",22,"keys",0,0],"உணர்திறன் அதிகரித்தல்"],[["ORDER",22,"keys",0,1],"திரும்பத் திரும்ப வரும் அச்சுறுத்தலுக்குப் பிறகு எச்சரிக்கை மணி இன்னும் வேகமாகவும் வலுவாகவும் அடிக்கிறது"],[["ORDER",22,"keys",1,0],"சேதம் அல்ல, தகவமைப்பு"],[["ORDER",22,"keys",1,1],"ஆபத்தான சூழலில் மூளை தன் வேலையைச் செய்ததால் ஏற்பட்ட மாற்றங்களே இவை"],[["ORDER",22,"keys",2,0],"நெகிழ்வு"],[["ORDER",22,"keys",2,1],"மூளை வாழ்நாள் முழுவதும் மாற முடியும்"],[["ORDER",22,"keys",3,0],"உறவு வழியான சீரமைப்பு"],[["ORDER",22,"keys",3,1],"பாதுகாப்பான, இசைந்துணரும் உறவுகள் சுகமடைதலுக்கு மையமானவை"],[["ORDER",22,"tr",0],"முதலில் உங்கள் எச்சரிக்கை அறிகுறிகளையும் அமைதிப்படுத்தும் கருவிகளையும் கற்றுக்கொள்ளுங்கள்"],[["ORDER",22,"tr",1],"நிலையானதாக உணரப்படும் உறவுகளையும் சிகிச்சையையும் தேர்ந்தெடுங்கள்"],[["ORDER",22,"tr",2],"உடனடித் தீர்வுகளை அல்ல, மெதுவான ஆனால் உண்மையான மாற்றத்தை எதிர்பாருங்கள்"],[["ORDER",22,"rl"],"கடந்த காலத்தில் பயம் எழுதியதை, இப்போதைய பாதுகாப்பான அன்பு மாற்றி எழுதத் தொடங்கலாம்."],[["ORDER",22,"simple"],"பிள்ளைகளுக்குப் பயமுறுத்தும் விஷயங்கள் தொடர்ந்து நடக்கும்போது, அவர்களின் மூளை எச்சரிக்கையாகவே இருக்கிறது. பாதுகாப்பான, அன்பான கவனிப்பு அது சுகமடைய உதவுகிறது."],[["ORDER",23,"t"],"உடலியல் பெருமூச்சு"],[["ORDER",23,"time"],"1–2 நிமிடம்"],[["ORDER",23,"u"],"மன அழுத்தத்தைக் குறைக்க அறியப்பட்ட மிக வேகமான மூச்சுப் பயிற்சி: மூக்கு வழியாக இரண்டு முறை உள்ளிழுத்து, வாய் வழியாக ஒரு நீண்ட மூச்சை வெளியே விடுதல்."],[["ORDER",23,"steps",0],"நுரையீரல் நிறைந்ததாக உணரும் வரை மூக்கு வழியாக மூச்சை உள்ளிழுங்கள்"],[["ORDER",23,"steps",1],"அதன் மேல் மூக்கு வழியாக இரண்டாவதாக ஒரு சிறிய மூச்சை உள்ளிழுங்கள்"],[["ORDER",23,"steps",2],"நுரையீரல் காலியாகும் வரை, உள்ளிழுத்ததை விட நீண்ட நேரம், வாய் வழியாக மெதுவாக மூச்சை வெளியே விடுங்கள்"],[["ORDER",23,"steps",3],"3–5 முறை திரும்பச் செய்யுங்கள்"],[["ORDER",23,"steps",4],"உங்கள் தோள்களும் தாடையும் தளர்வதைக் கவனியுங்கள்"],[["ORDER",23,"fixes",0,0],"எனக்குத் தலை சுற்றுவது போல இருக்கிறது"],[["ORDER",23,"fixes",0,1],"மெதுவாகச் செய்து, குறைவான சுற்றுகள் செய்யுங்கள்; இடையில் சாதாரணமாக மூச்சு விடுங்கள்"],[["ORDER",23,"fixes",1,0],"அதைப் பயன்படுத்த மறந்துவிடுகிறேன்"],[["ORDER",23,"fixes",1,1],"அதை ஒரு குறிப்போடு இணையுங்கள்: மின்னஞ்சலைத் திறப்பதற்கு முன், கடினமான உரையாடல்களுக்கு முன்"],[["ORDER",23,"fixes",2,0],"இது வேடிக்கையாகத் தோன்றுகிறது"],[["ORDER",23,"fixes",2,1],"அமைதியாகச் செய்யுங்கள்; யாருக்கும் தெரியாது"],[["ORDER",23,"why"],"நீண்ட வெளிமூச்சுகள் வேகஸ் நரம்பைச் செயல்படுத்தி இதயத் துடிப்பைக் குறைக்கின்றன. தினமும் சுழற்சி முறையில் பெருமூச்சு விடுவது, மன விழிப்புணர்வுத் தியானத்தை விட மனநிலையை அதிகம் மேம்படுத்தியது என்று 2023-ல் நடந்த ஒரு Stanford ஆய்வு கண்டறிந்தது."],[["ORDER",23,"simple"],"மூக்கு வழியாக மூச்சை உள்ளிழுங்கள், பிறகு இன்னும் கொஞ்சம் உறிஞ்சுங்கள், பிறகு வாய் வழியாக மெதுவாக ஊதுங்கள். இரண்டு மூன்று முறை செய்தால் உங்கள் உடல் வேகமாக அமைதியாகும்."],[["ORDER",24,"t"],"பெட்டி மூச்சுப் பயிற்சி"],[["ORDER",24,"time"],"2–4 நிமிடம்"],[["ORDER",24,"u"],"அழுத்தத்தின் கீழ் மனதை நிலைப்படுத்த, சீரான, சதுர வடிவ மூச்சுப் பயிற்சி."],[["ORDER",24,"steps",0],"4 எண்ணும் வரை மூச்சை உள்ளிழுங்கள்"],[["ORDER",24,"steps",1],"4 எண்ணும் வரை நிறுத்தி வையுங்கள்"],[["ORDER",24,"steps",2],"4 எண்ணும் வரை மூச்சை வெளியே விடுங்கள்"],[["ORDER",24,"steps",3],"மூச்சு இல்லாமல் 4 எண்ணும் வரை நிறுத்தி வையுங்கள்"],[["ORDER",24,"steps",4],"உங்கள் கண்களாலோ விரலாலோ ஒரு சதுரம் வரைந்தபடி 2–4 நிமிடங்கள் திரும்பச் செய்யுங்கள்"],[["ORDER",24,"fixes",0,0],"மூச்சை நிறுத்தி வைப்பது சங்கடமாக இருக்கிறது"],[["ORDER",24,"fixes",0,1],"நிறுத்தும் நேரத்தை 2 எண்ணிக்கையாகக் குறையுங்கள், அல்லது விட்டுவிடுங்கள்"],[["ORDER",24,"fixes",1,0],"என் மனம் அலைபாய்கிறது"],[["ORDER",24,"fixes",1,1],"விரல்களில் எண்ணுங்கள்"],[["ORDER",24,"fixes",2,0],"இது என்னை அமைதிப்படுத்துவதில்லை"],[["ORDER",24,"fixes",2,1],"அதற்குப் பதிலாக நீண்ட வெளிமூச்சுப் பயிற்சியை முயற்சி செய்யுங்கள்"],[["ORDER",24,"why"],"சீரான ஒழுங்கும் மூச்சுக் கட்டுப்பாடும் மூளைக்கு முன்கூட்டியே தெரிந்த ஒரு கவனப் புள்ளியைக் கொடுத்து, விழிப்புநிலையைக் குறைக்கின்றன."],[["ORDER",24,"simple"],"4 எண்ணும் வரை உள்ளிழுங்கள், 4 வரை நிறுத்துங்கள், 4 வரை வெளியே விடுங்கள், 4 வரை நிறுத்துங்கள்; ஒரு சதுரம் வரைவது போல. இது நீங்கள் நிலையாக உணர உதவுகிறது."],[["ORDER",25,"t"],"நீண்ட வெளிமூச்சுப் பயிற்சி"],[["ORDER",25,"time"],"2–5 நிமிடம்"],[["ORDER",25,"u"],"உடலை அமைதியை நோக்கித் திருப்ப, உள்மூச்சை விட வெளிமூச்சை நீளமாக்குங்கள்."],[["ORDER",25,"steps",0],"பாதங்களைத் தரையில் வைத்து உட்காருங்கள் அல்லது நில்லுங்கள்"],[["ORDER",25,"steps",1],"மூக்கு வழியாக 4 எண்ணும் வரை மூச்சை உள்ளிழுங்கள்"],[["ORDER",25,"steps",2],"உதடுகளைக் குவித்து 6–8 எண்ணும் வரை மெதுவாக மூச்சை வெளியே விடுங்கள்"],[["ORDER",25,"steps",3],"வலுக்கட்டாயமாக அல்ல, மென்மையாகச் செய்யுங்கள்"],[["ORDER",25,"steps",4],"10 மூச்சுகள் தொடருங்கள்"],[["ORDER",25,"fixes",0,0],"மூச்சில் கவனம் செலுத்தும்போது எனக்குப் பதட்டமாகிறது"],[["ORDER",25,"fixes",0,1],"கண்களைத் திறந்தே வைத்து, மூச்சு விடும்போது அமைதி தரும் ஏதாவது ஒன்றைப் பாருங்கள்"],[["ORDER",25,"fixes",1,0],"என்னால் அவ்வளவு நீண்ட நேரம் மூச்சை வெளியே விட முடியவில்லை"],[["ORDER",25,"fixes",1,1],"3 எண்ணிக்கை உள்ளே, 5 எண்ணிக்கை வெளியே என்று செய்யுங்கள்"],[["ORDER",25,"fixes",2,0],"பீதியின்போது இது உதவுவதில்லை"],[["ORDER",25,"fixes",2,1],"நிலைப்படுத்தும் பயிற்சியோடு (5-4-3-2-1) சேர்த்துச் செய்யுங்கள்"],[["ORDER",25,"why"],"வெளிமூச்சு, பாராசிம்பதெடிக் நரம்பு மண்டலம் வழியாக இதயத் துடிப்பைக் குறைக்கிறது."],[["ORDER",25,"simple"],"மெதுவாக மூச்சை உள்ளிழுங்கள், பிறகு சூடான சூப்பை ஊதுவது போல இன்னும் மெதுவாக வெளியே விடுங்கள். நீண்ட வெளிமூச்சு உங்கள் இதயத்தை அமைதிப்படுத்துகிறது."],[["ORDER",26,"t"],"5-4-3-2-1 நிலைப்படுத்தும் பயிற்சி"],[["ORDER",26,"time"],"3 நிமிடம்"],[["ORDER",26,"u"],"பதட்டமாக இருக்கும்போதோ, துண்டிக்கப்பட்டதுபோல் உணரும்போதோ, பழைய நினைவு மீண்டும் நடப்பதுபோல் தோன்றும்போதோ (ஃப்ளாஷ்பேக்), உங்கள் புலன்களைப் பயன்படுத்தி இந்தத் தருணத்துக்குத் திரும்புங்கள்."],[["ORDER",26,"steps",0],"நீங்கள் பார்க்கக்கூடிய 5 பொருட்களைச் சொல்லுங்கள்"],[["ORDER",26,"steps",1],"நீங்கள் உணரக்கூடிய 4 விஷயங்களைச் சொல்லுங்கள் (பாதங்கள், நாற்காலி, துணி)"],[["ORDER",26,"steps",2],"நீங்கள் கேட்கக்கூடிய 3 ஒலிகளைச் சொல்லுங்கள்"],[["ORDER",26,"steps",3],"நீங்கள் முகரக்கூடிய 2 வாசனைகளைச் சொல்லுங்கள்"],[["ORDER",26,"steps",4],"நீங்கள் சுவைக்கக்கூடிய 1 பொருளைச் சொல்லுங்கள், அல்லது உங்களுக்கே சொல்லிக்கொள்ள ஒரு அன்பான வார்த்தையைச் சொல்லுங்கள்"],[["ORDER",26,"steps",5],"இன்றைய தேதியையும் நீங்கள் இருக்கும் இடத்தையும் சொல்லுங்கள்"],[["ORDER",26,"fixes",0,0],"பட்டியலில் என்னால் கவனம் செலுத்த முடியவில்லை"],[["ORDER",26,"fixes",0,1],"“நான் பார்க்கும் 5 பொருட்கள்” என்பதை மட்டும் மெதுவாக, சத்தமாகச் செய்யுங்கள்"],[["ORDER",26,"fixes",1,0],"இன்னும் தொலைவில் இருப்பதுபோல் உணர்கிறேன்"],[["ORDER",26,"fixes",1,1],"சொரசொரப்பான அல்லது குளிர்ந்த ஏதாவது ஒன்றைப் பிடித்துக்கொள்ளுங்கள்; எழுந்து நின்று பாதங்களைத் தரையில் அழுத்துங்கள்"],[["ORDER",26,"fixes",2,0],"இது பழைய நினைவுகளை எழுப்புகிறது"],[["ORDER",26,"fixes",2,1],"கண்களை இன்னும் அகலமாகத் திறந்து, நிறங்களை விவரமாக விவரியுங்கள்"],[["ORDER",26,"why"],"புலன் விவரங்கள் திசைப்படுத்தும் வலைப்பின்னல்களை இயக்கி, “நான் இங்கே, இப்போது இருக்கிறேன்” என்று மூளைக்குச் சொல்கின்றன."],[["ORDER",26,"simple"],"நீங்கள் பார்க்கும் 5, தொடக்கூடிய 4, கேட்கும் 3, முகரும் 2, சுவைக்கும் 1 விஷயங்களைச் சொல்லுங்கள். இது உங்களை இந்தத் தருணத்துக்குத் திரும்பக் கொண்டுவருகிறது."],[["ORDER",27,"t"],"பாதுகாப்பை நோக்கித் திசைப்படுத்தல்"],[["ORDER",27,"time"],"2 நிமிடம்"],[["ORDER",27,"u"],"நரம்பு மண்டலத்துக்குப் பாதுகாப்பைச் சமிக்ஞை செய்ய, உங்கள் கண்கள் அறையை மெதுவாகச் சுற்றிப் பார்க்கட்டும்."],[["ORDER",27,"steps",0],"உங்கள் தலையும் கண்களும் அறையைச் சுற்றி மெதுவாகத் திரும்பட்டும்"],[["ORDER",27,"steps",1],"எது உங்கள் கண்ணை ஈர்க்கிறது என்று கவனியுங்கள், குறிப்பாக இனிமையான நிறங்கள் அல்லது பொருட்கள்"],[["ORDER",27,"steps",2],"சாதாரணமான அல்லது இனிமையான ஒன்றின் மேல் சற்று நிறுத்திப் பாருங்கள்"],[["ORDER",27,"steps",3],"வெளியேறும் வழிகள், வெளிச்சம், இடம் ஆகியவற்றைக் கவனியுங்கள்"],[["ORDER",27,"steps",4],"சரிபாருங்கள்: உங்கள் உடலில் ஏதாவது மாறியிருக்கிறதா?"],[["ORDER",27,"fixes",0,0],"சுற்றிப் பார்ப்பது என்னை இன்னும் அதிக எச்சரிக்கையாக்குகிறது"],[["ORDER",27,"fixes",0,1],"இன்னும் மெதுவாகச் செய்து, அமைதி தரும் ஒரு பொருளின் மேல் கண்களை ஓய்வெடுக்க விடுங்கள்"],[["ORDER",27,"fixes",1,0],"எதுவுமே பாதுகாப்பாகத் தோன்றவில்லை"],[["ORDER",27,"fixes",1,1],"மிகச் சிறிய பாதுகாப்பான ஒன்றை நோக்கித் திரும்புங்கள் (ஒரு செடி, ஒரு குவளை)"],[["ORDER",27,"fixes",2,0],"தனிமையான இடத்தில் இல்லை"],[["ORDER",27,"fixes",2,1],"சாதாரணமாகச் சுற்றிப் பார்ப்பது போலவே இதைச் செய்யுங்கள்"],[["ORDER",27,"why"],"திசைப்படுத்தல் பாலூட்டிகளின் மிகப் பழமையான ஒரு பதில்செயல்: சுற்றிப் பார்த்து, ஆபத்து எதுவும் இல்லை என்று கண்டால் எச்சரிக்கை மணி அமைதியாகிறது."],[["ORDER",27,"simple"],"அறையை மெதுவாகச் சுற்றிப் பாருங்கள். நீங்கள் இங்கே பாதுகாப்பாக இருக்கிறீர்கள் என்று கவனியுங்கள். உங்கள் கண்கள் சரிபார்க்கும்போது உங்கள் உடல் தளர்கிறது."],[["ORDER",28,"t"],"அதிகமாகத் தாங்க முடியாதபோது TIPP (DBT)"],[["ORDER",28,"time"],"5–10 நிமிடம்"],[["ORDER",28,"u"],"உணர்வு மிக அதிகமாக இருக்கும்போது (7+/10) பயன்படுத்த, DBT (இயங்கியல் நடத்தை சிகிச்சை) தரும் நான்கு வேகமான, உடல் சார்ந்த திறன்கள்."],[["ORDER",28,"steps",0],"வெப்பநிலை (Temperature): முகத்தில் குளிர்ந்த தண்ணீரைத் தெளியுங்கள், அல்லது 30 வினாடிகள் கண்களின் மேல் குளிர்ந்த ஒத்தடம் வையுங்கள்"],[["ORDER",28,"steps",1],"தீவிர உடற்பயிற்சி (Intense exercise): 5–10 நிமிடங்கள் வேகமாக நடத்தல், படிக்கட்டு ஏறுதல் அல்லது குதித்தல் பயிற்சி"],[["ORDER",28,"steps",2],"சீரான மூச்சு (Paced breathing): 2 நிமிடங்கள் உள்ளிழுப்பதை விட நீண்ட நேரம் மூச்சை வெளியே விடுங்கள்"],[["ORDER",28,"steps",3],"இணைந்த தசைத் தளர்வு (Paired muscle relaxation): மூச்சை உள்ளிழுக்கும்போது ஒரு தசைக் குழுவை இறுக்குங்கள், வெளியே விடும்போது தளர்த்துங்கள்"],[["ORDER",28,"fixes",0,0],"எனக்கு இதய நோய் அல்லது உணவு உண்ணும் கோளாறு இருக்கிறது"],[["ORDER",28,"fixes",0,1],"வெப்பநிலையையும் தீவிர உடற்பயிற்சியையும் விட்டுவிடுங்கள்; முதலில் ஒரு மருத்துவரிடம் கேளுங்கள்"],[["ORDER",28,"fixes",1,0],"என்னால் அதிகம் அசைய முடியாது"],[["ORDER",28,"fixes",1,1],"சீரான மூச்சையும் தசைத் தளர்வையும் மட்டும் பயன்படுத்துங்கள்"],[["ORDER",28,"fixes",2,0],"உணர்வு பின்னர் திரும்ப வருகிறது"],[["ORDER",28,"fixes",2,1],"அடுத்ததாகச் செய்ய ஒரு திறனைத் திட்டமிடுங்கள் (பேசுதல், நாட்குறிப்பு எழுதுதல், பிரச்சினைக்குத் தீர்வு காணுதல்)"],[["ORDER",28,"why"],"முகத்தில் குளிர்ந்த தண்ணீர் படும்போது “டைவ் ரிஃப்ளெக்ஸ்” எனும் இயற்கை எதிர்வினை தூண்டப்பட்டு, இதயத் துடிப்பு குறைகிறது; உடற்பயிற்சி மன அழுத்த ஹார்மோன்களை எரித்துவிடுகிறது."],[["ORDER",28,"caution"],"உங்களுக்கு இதயப் பிரச்சினைகள், குறைந்த இரத்த அழுத்தம் அல்லது உணவுக் கோளாறு இருந்தால், முதலில் மருத்துவரிடம் கேளுங்கள்."],[["ORDER",28,"simple"],"உணர்வுகள் மிகப் பெரிதாக இருக்கும்போது: முகத்தில் குளிர்ந்த தண்ணீர், சிறிது ஓட்டம் அல்லது குதித்தல், மெதுவான மூச்சு, தசைகளைத் தளர்த்துதல்."],[["ORDER",29,"t"],"பெயரிடுங்கள், அடக்குங்கள்"],[["ORDER",29,"time"],"1 நிமிடம்"],[["ORDER",29,"u"],"உணர்வை வார்த்தைகளில் சொல்லுங்கள். உணர்வுகளுக்குப் பெயரிடுவது அமிக்டாலாவின் (பய எச்சரிக்கை மையம்) செயல்பாட்டைக் குறைக்கிறது."],[["ORDER",29,"steps",0],"நிதானித்து, நீங்கள் என்ன உணர்கிறீர்கள் என்று கவனியுங்கள்"],[["ORDER",29,"steps",1],"உடலில் உணர்வைக் கண்டுபிடியுங்கள் (அது எங்கே இருக்கிறது?)"],[["ORDER",29,"steps",2],"துல்லியமாகப் பெயரிடுங்கள்: “நான் ஏமாற்றமாகவும் கொஞ்சம் வெட்கமாகவும் உணர்கிறேன்”"],[["ORDER",29,"steps",3],"0–10 அளவில் மதிப்பிடுங்கள்"],[["ORDER",29,"steps",4],"கேளுங்கள்: “இந்த உணர்வுக்கு என்ன தேவை?”"],[["ORDER",29,"fixes",0,0],"நான் என்ன உணர்கிறேன் என்று எனக்குத் தெரியவில்லை"],[["ORDER",29,"fixes",0,1],"கோபம், சோகம், மகிழ்ச்சி, பயம் அல்லது அவமானம் என்பதிலிருந்து தொடங்குங்கள்"],[["ORDER",29,"fixes",1,0],"பெயரிட்டால் அது இன்னும் பெரிதாகிறது"],[["ORDER",29,"fixes",1,1],"சற்று இடைவெளி கொடுங்கள்: “நான் … உணர்வதைக் கவனிக்கிறேன்”"],[["ORDER",29,"fixes",2,0],"அந்த உணர்வுக்காக என்னையே குறை சொல்கிறேன்"],[["ORDER",29,"fixes",2,1],"“அது புரிந்துகொள்ளக்கூடியதுதான், ஏனென்றால்…” என்று சேர்த்துச் சொல்லுங்கள்"],[["ORDER",29,"why"],"உணர்வுக்குப் பெயரிடுவது முன்மூளைப் புறணியைச் செயல்படுத்துகிறது; அது அமிக்டாலாவை அமைதிப்படுத்துகிறது (Lieberman, UCLA)."],[["ORDER",29,"simple"],"நீங்கள் உணர்வதைச் சொல்லுங்கள்: “எனக்குப் பயமாக இருக்கிறது.” உணர்வுக்குப் பெயர் வைத்தால் அது சிறியதாகிறது."],[["ORDER",30,"t"],"எண்ணங்களிலிருந்து விலகி நிற்றல் (Cognitive Defusion)"],[["ORDER",30,"time"],"2 நிமிடம்"],[["ORDER",30,"u"],"ஒட்டிக்கொள்ளும் எண்ணங்களிலிருந்து ஒரு அடி பின்வாங்குங்கள்; அப்போது அவற்றின் பிடி தளரும். இது ACT முறையிலிருந்து வருகிறது."],[["ORDER",30,"steps",0],"எண்ணத்தைக் கவனியுங்கள் (உதா. “நான் ஒன்றுக்கும் உதவாதவன்/உதவாதவள்”)"],[["ORDER",30,"steps",1],"சேர்த்துச் சொல்லுங்கள்: “நான் ஒன்றுக்கும் உதவாதவன் என்ற எண்ணம் எனக்கு வருகிறது”"],[["ORDER",30,"steps",2],"பிறகு: “… என்ற எண்ணம் எனக்கு வருவதை நான் கவனிக்கிறேன்”"],[["ORDER",30,"steps",3],"அந்தக் கதைக்கு ஒரு பெயர் வையுங்கள் (“ஆ, இது ‘நான் போதாது’ கதை”)"],[["ORDER",30,"steps",4],"நீங்கள் செய்துகொண்டிருந்த வேலைக்குக் கவனத்தைத் திருப்புங்கள்"],[["ORDER",30,"fixes",0,0],"அந்த எண்ணம் இன்னும் உண்மையாகவே தோன்றுகிறது"],[["ORDER",30,"fixes",0,1],"அதை நம்பாமல் இருக்க வேண்டியதில்லை; அதைக் கொஞ்சம் தளர்வாகப் பிடித்தால் போதும்"],[["ORDER",30,"fixes",1,0],"அது திரும்பவும் வருகிறது"],[["ORDER",30,"fixes",1,1],"அது சாதாரணம்தான்; ஒவ்வொரு முறையும் மீண்டும் விலகி நில்லுங்கள்"],[["ORDER",30,"fixes",2,0],"உணர்வை அலட்சியம் செய்வது போல் தோன்றுகிறது"],[["ORDER",30,"fixes",2,1],"அதைத் தன்னிரக்கத்துடன் சேர்த்துச் செய்யுங்கள்"],[["ORDER",30,"why"],"ஒரு எண்ணத்துடன் உங்களுக்குள்ள உறவை மாற்றும்போது, அதனுடன் வாதாடாமலேயே அதன் வலிமை குறைகிறது."],[["ORDER",30,"simple"],"பயமுறுத்தும் எண்ணத்துக்கு முன் “… என்ற எண்ணம் எனக்கு வருகிறது” என்று சொல்லுங்கள். எண்ணம் வெறும் எண்ணம்தான் என்று அது நினைவூட்டுகிறது."],[["ORDER",31,"t"],"உந்துதல் அலையில் மிதத்தல் (Urge Surfing)"],[["ORDER",31,"time"],"10–20 நிமிடம்"],[["ORDER",31,"u"],"ஒரு ஆசையையோ உந்துதலையோ செயல்படுத்தாமல், ஒரு அலையைப் போல் அதன்மேல் மிதந்து கடந்து செல்லுங்கள்."],[["ORDER",31,"steps",0],"உந்துதலைக் கவனித்து அதற்குப் பெயரிடுங்கள் (“இதோ, பார்க்க / சாப்பிட / குடிக்க வேண்டும் என்ற உந்துதல்”)"],[["ORDER",31,"steps",1],"0–10 அளவில் மதிப்பிடுங்கள்"],[["ORDER",31,"steps",2],"அது உடலில் எங்கே இருக்கிறது என்று கண்டுபிடியுங்கள்"],[["ORDER",31,"steps",3],"அதை நோக்கி மூச்சு விடுங்கள்; அது எழும்பி, உச்சத்தை அடைந்து, இறங்குவதைப் பாருங்கள்"],[["ORDER",31,"steps",4],"சில நிமிடங்களுக்கு ஒருமுறை மீண்டும் மதிப்பிடுங்கள்"],[["ORDER",31,"steps",5],"கவனியுங்கள்: எதுவும் செய்யாமலேயே உந்துதல்கள் கடந்துபோகின்றன"],[["ORDER",31,"fixes",0,0],"உந்துதல் மிகவும் வலிமையாக இருக்கிறது"],[["ORDER",31,"fixes",0,1],"வெறும் 10 நிமிடம் தள்ளிப்போடுங்கள், பிறகு முடிவு செய்யுங்கள்"],[["ORDER",31,"fixes",1,0],"நான் விட்டுக்கொடுத்துவிடுகிறேன்"],[["ORDER",31,"fixes",1,1],"அவமான உணர்வு இல்லாமல் என்ன நடந்தது என்று குறித்துக்கொள்ளுங்கள்; அடுத்த முறை மீண்டும் முயலுங்கள்"],[["ORDER",31,"fixes",2,0],"உந்துதல்கள் வந்துகொண்டே இருக்கின்றன"],[["ORDER",31,"fixes",2,1],"தூண்டும் விஷயங்களைக் குறைக்க சுற்றுச்சூழலை மாற்றுங்கள்"],[["ORDER",31,"why"],"ஒரு உந்துதலுக்கு இடம் கொடுக்காமல் அது கடந்துபோகும் ஒவ்வொரு முறையும், அந்தப் பழக்கச் சுழற்சி பலவீனமடைகிறது (extinction learning – பழையதை மறக்கும் கற்றல்)."],[["ORDER",31,"simple"],"செய்யக்கூடாத ஒன்றைச் செய்ய ஆசை வரும்போது, காத்திருந்து, அந்த ஆசை அலை போல எழும்பி இறங்குவதைப் பாருங்கள்."],[["ORDER",32,"t"],"STOP திறன்"],[["ORDER",32,"time"],"1 நிமிடம்"],[["ORDER",32,"u"],"தூண்டுதலுக்கும் எதிர்வினைக்கும் இடையே ஒரு சிறிய இடைநிறுத்தம்."],[["ORDER",32,"steps",0],"நிறுத்துங்கள் (Stop): ஒரு கணம் அசையாமல் நில்லுங்கள்"],[["ORDER",32,"steps",1],"ஒரு அடி பின்வாங்குங்கள் (Take a step back): ஒருமுறை ஆழமாக மூச்சு விடுங்கள்"],[["ORDER",32,"steps",2],"கவனியுங்கள் (Observe): எனக்குள்ளும் என்னைச் சுற்றியும் என்ன நடக்கிறது?"],[["ORDER",32,"steps",3],"கவனத்துடன் தொடருங்கள் (Proceed mindfully): என் மதிப்பீடுகளுக்கு ஏற்ற செயல் எது?"],[["ORDER",32,"fixes",0,0],"நினைவு வருவதற்கு முன்பே நான் எதிர்வினை செய்துவிடுகிறேன்"],[["ORDER",32,"fixes",0,1],"சிறிய எரிச்சல்களின்போது தினமும் STOP பயிற்சி செய்யுங்கள்"],[["ORDER",32,"fixes",1,0],"நிறுத்துகிறேன், ஆனாலும் பிறகு எதிர்வினை செய்துவிடுகிறேன்"],[["ORDER",32,"fixes",1,1],"உடல்ரீதியாகவும் பின்வாங்குங்கள் (அறையை விட்டு வெளியே போங்கள்)"],[["ORDER",32,"fixes",2,0],"STOP செய்யும்போது என்னால் யோசிக்க முடியவில்லை"],[["ORDER",32,"fixes",2,1],"மூச்சு மட்டும் விடுங்கள்; யோசிப்பது பிறகு வரும்"],[["ORDER",32,"why"],"ஒரு இடைநிறுத்தம், எச்சரிக்கை மணியைப் பிடிக்க முன்மூளைப் புறணிக்கு நேரம் கொடுக்கிறது."],[["ORDER",32,"simple"],"நில்லுங்கள். ஒரு மூச்சு விடுங்கள். என்ன நடக்கிறது என்று பாருங்கள். பிறகு என்ன செய்வது என்று தேர்ந்தெடுங்கள்."],[["ORDER",33,"t"],"தன்னிரக்க இடைவேளை"],[["ORDER",33,"time"],"3 நிமிடம்"],[["ORDER",33,"u"],"வலி அல்லது தோல்விக்கு மூன்று படிகளில் பதிலளித்தல் (Kristin Neff)."],[["ORDER",33,"steps",0],"கவனம்: “இது வேதனையான ஒரு நேரம்” அல்லது “இது கடினமாக இருக்கிறது”"],[["ORDER",33,"steps",1],"எல்லோருக்கும் பொதுவானது: “போராட்டம் மனிதனாக இருப்பதன் ஒரு பகுதி. மற்றவர்களும் இப்படி உணர்கிறார்கள்”"],[["ORDER",33,"steps",2],"அன்பு: நெஞ்சின் மேல் கை வையுங்கள்; “நான் என்னிடம் அன்பாக இருப்பேனாக” அல்லது “எனக்கு என்ன தேவை?”"],[["ORDER",33,"steps",3],"ஒரு சிறிய அக்கறைச் செயலால் பதிலளியுங்கள்"],[["ORDER",33,"fixes",0,0],"இது போலியாகத் தோன்றுகிறது"],[["ORDER",33,"fixes",0,1],"ஒரு நண்பரிடம் நீங்கள் சொல்லும் வார்த்தைகளைப் பயன்படுத்துங்கள்"],[["ORDER",33,"fixes",1,0],"முதலில் இன்னும் மோசமாக உணர்கிறேன்"],[["ORDER",33,"fixes",1,1],"இது பொதுவானது; அன்பு வரும்போது பழைய வலி மேலே வருகிறது; சுருக்கமாக வைத்துக்கொள்ளுங்கள்"],[["ORDER",33,"fixes",2,0],"எனக்கு இதற்குத் தகுதியில்லை என்று நினைக்கிறேன்"],[["ORDER",33,"fixes",2,1],"ஒரு வாரத்துக்கு ஒரு சோதனையாக எப்படியும் செய்து பாருங்கள்"],[["ORDER",33,"why"],"தன்னிரக்கம் ஆறுதல் அமைப்பைச் செயல்படுத்தி, அச்சுறுத்தல் எதிர்வினைகளைக் குறைக்கிறது (Gilbert, Neff)."],[["ORDER",33,"simple"],"நெஞ்சின் மேல் கை வைத்துச் சொல்லுங்கள்: “இது கடினமாக இருக்கிறது. மற்றவர்களும் இப்படி உணர்கிறார்கள். நான் என்னிடம் அன்பாக இருக்கலாம்.”"],[["ORDER",34,"t"],"எதிர்ச் செயல் (DBT)"],[["ORDER",34,"time"],"5–30 நிமிடம்"],[["ORDER",34,"u"],"ஒரு உணர்வு உண்மை நிலைக்குப் பொருந்தாதபோது, அது தூண்டுவதற்கு எதிரானதைச் செய்யுங்கள்."],[["ORDER",34,"steps",0],"உணர்வுக்கும் அதன் உந்துதலுக்கும் பெயரிடுங்கள் (அவமானம் → ஒளிந்துகொள்ளுதல்)"],[["ORDER",34,"steps",1],"உண்மைகளைச் சரிபாருங்கள்: இந்தச் சூழ்நிலைக்கு இது பொருந்துகிறதா?"],[["ORDER",34,"steps",2],"பொருந்தவில்லை என்றால், எதிர்ச் செயலைத் தேர்ந்தெடுங்கள் (அவமானம் → முன்வந்து நிற்றல்; பயம் → அணுகுதல்; சோகம் → சுறுசுறுப்பாக இயங்குதல்)"],[["ORDER",34,"steps",3],"முழுமையாகச் செய்யுங்கள்: உடல் நிலை, குரல், முகம்"],[["ORDER",34,"steps",4],"உணர்வு மாறும் வரை திரும்பத் திரும்பச் செய்யுங்கள்"],[["ORDER",34,"fixes",0,0],"உணர்வு உண்மைகளுக்குப் பொருந்துகிறது"],[["ORDER",34,"fixes",0,1],"அதற்குப் பதிலாகப் பிரச்சினையைத் தீர்க்கும் வழியைப் பயன்படுத்துங்கள்"],[["ORDER",34,"fixes",1,0],"அரை மனதோடு செய்கிறேன்"],[["ORDER",34,"fixes",1,1],"உடல் நிலையையும் குரலையும் கூட மாற்றுங்கள்"],[["ORDER",34,"fixes",2,0],"இது பாதுகாப்பற்றதாகத் தோன்றுகிறது"],[["ORDER",34,"fixes",2,1],"முதலில் சிறிய, பாதுகாப்பான ஒரு வடிவத்தைத் தேர்ந்தெடுங்கள்"],[["ORDER",34,"why"],"வித்தியாசமாகச் செயல்படுவது மூளைக்குப் புதிய ஆதாரத்தைக் கொடுக்கிறது; இதனால் உணர்ச்சி எதிர்வினை படிப்படியாக மாறுகிறது."],[["ORDER",34,"simple"],"ஒரு உணர்வு உங்களை ஒளிந்துகொள்ளவோ அடிக்கவோ சொல்லும்போது, அதற்கு எதிரானதைச் செய்யுங்கள்: மென்மையாக அதை நோக்கிச் செல்லுங்கள் அல்லது அன்பாக நடந்துகொள்ளுங்கள்."],[["ORDER",35,"t"],"2 நிமிடத் தொடக்கம்"],[["ORDER",35,"time"],"2 நிமிடம்"],[["ORDER",35,"u"],"வெறும் இரண்டு நிமிடம் மட்டும் செய்வேன் என்று முடிவெடுத்து, தள்ளிப்போடுதலை வெல்லுங்கள்."],[["ORDER",35,"steps",0],"வேலையைத் தேர்ந்தெடுங்கள்"],[["ORDER",35,"steps",1],"அதன் 2 நிமிட வடிவத்தை முடிவு செய்யுங்கள் (“ஆவணத்தைத் திறந்து ஒரு வாக்கியம் எழுதுவேன்”)"],[["ORDER",35,"steps",2],"2 நிமிடத்துக்கு டைமர் வையுங்கள்"],[["ORDER",35,"steps",3],"இன்னும் யோசிப்பதற்கு முன், உடனே தொடங்குங்கள்"],[["ORDER",35,"steps",4],"டைமர் முடிந்ததும், நிறுத்தலாமா தொடரலாமா என்று தேர்ந்தெடுங்கள்"],[["ORDER",35,"fixes",0,0],"இன்னும் என்னால் தொடங்க முடியவில்லை"],[["ORDER",35,"fixes",0,1],"அதை இன்னும் சிறியதாக்குங்கள் (கோப்பைத் திறந்தால் மட்டும் போதும்)"],[["ORDER",35,"fixes",1,0],"நான் எப்போதும் 2 நிமிடத்தில் நிறுத்திவிடுகிறேன்"],[["ORDER",35,"fixes",1,1],"பரவாயில்லை; தொடங்கியதே ஒரு வெற்றி; பிறகு மீண்டும் செய்யுங்கள்"],[["ORDER",35,"fixes",2,0],"வேலை தெளிவாக இல்லை"],[["ORDER",35,"fixes",2,1],"அடுத்த படியை எழுதுவதில் அந்த 2 நிமிடங்களைச் செலவிடுங்கள்"],[["ORDER",35,"why"],"தொடங்குவது உந்துவேகத்தை உருவாக்குகிறது; டோபமைன் செயலுக்குப் பின்னால் வருகிறது, முன்னால் அல்ல."],[["ORDER",35,"simple"],"ஒரு வேலை மிகப் பெரிதாகத் தோன்றினால், இரண்டு நிமிடம் மட்டும் செய்யுங்கள். தொடங்குவதுதான் கடினமான பகுதி."],[["ORDER",36,"t"],"மனதைக் காலி செய்தல் (Brain Dump)"],[["ORDER",36,"time"],"10 நிமிடம்"],[["ORDER",36,"u"],"முடிக்காமல் மனதில் சுற்றிக்கொண்டிருக்கும் எல்லாவற்றையும் காகிதத்தில் இறக்கி வையுங்கள்; அப்போது உங்கள் மனம் அவற்றைப் பிடித்துக்கொண்டிருக்க வேண்டியதில்லை."],[["ORDER",36,"steps",0],"10 நிமிடத்துக்கு டைமர் வையுங்கள்"],[["ORDER",36,"steps",1],"மனதில் உள்ள எல்லாவற்றையும் எழுதுங்கள்: வேலைகள், கவலைகள், யோசனைகள், நினைவூட்டல்கள்"],[["ORDER",36,"steps",2],"இப்போதைக்கு வரிசைப்படுத்த வேண்டாம்"],[["ORDER",36,"steps",3],"இன்று முக்கியமான 1–3 விஷயங்களை வட்டமிடுங்கள்"],[["ORDER",36,"steps",4],"மீதியை நேரம் குறித்து வையுங்கள் அல்லது நீக்கிவிடுங்கள்"],[["ORDER",36,"fixes",0,0],"பட்டியலைப் பார்த்தாலே மலைப்பாக இருக்கிறது"],[["ORDER",36,"fixes",0,1],"ஒரே ஒரு விஷயத்தை மட்டும் வட்டமிடுங்கள்"],[["ORDER",36,"fixes",1,0],"புதிய எண்ணங்கள் வந்துகொண்டே இருக்கின்றன"],[["ORDER",36,"fixes",1,1],"நாள் முழுவதும் குறித்துக்கொள்ள ஒரு குறிப்பைத் திறந்தே வையுங்கள்"],[["ORDER",36,"fixes",2,0],"காகிதம் தொலைந்துபோகிறது"],[["ORDER",36,"fixes",2,1],"ஒரே நோட்டுப் புத்தகத்தை அல்லது ஒரே ஆப்பைத் தொடர்ந்து பயன்படுத்துங்கள்"],[["ORDER",36,"why"],"முடிக்காத வேலைகள் கவனத்தை இழுத்துக்கொண்டே இருக்கின்றன (Zeigarnik விளைவு); நம்பகமான ஒரு திட்டம் அவற்றை விடுவிக்கிறது (Masicampo & Baumeister)."],[["ORDER",36,"simple"],"உங்கள் தலையில் உள்ள எல்லாவற்றையும் காகிதத்தில் எழுதுங்கள். அது உங்கள் பரபரப்பான மனதைக் காலி செய்கிறது."],[["ORDER",37,"t"],"நிலை மாற்றும் பட்டியல்"],[["ORDER",37,"time"],"2–10 நிமிடம்"],[["ORDER",37,"u"],"அடுத்த வேலைக்கு ஏற்ற நிலைக்கு வர, உங்கள் இப்போதைய நிலைக்குப் பொருந்தும் ஒரு கருவியைத் தேர்ந்தெடுங்கள்."],[["ORDER",37,"steps",0],"உங்கள் நிலைக்குப் பெயரிடுங்கள்: பரபரப்பு, சோர்வு, மந்தம், சிதறல் அல்லது மலைப்பு"],[["ORDER",37,"steps",1],"பரபரப்பு: நீண்ட மூச்சு வெளியேற்றம், மெதுவான நடை, மங்கலான வெளிச்சம், சூடான பானம்"],[["ORDER",37,"steps",2],"சோர்வு அல்லது மந்தம்: எழுந்து நில்லுங்கள், வேகமான நடை, பகல் வெளிச்சம், குளிர்ந்த தண்ணீர், உற்சாகமான இசை"],[["ORDER",37,"steps",3],"சிதறல்: மனதைக் காலி செய்தல், திறந்திருக்கும் டேப்களை மூடுதல், ஒரே வேலை, டைமர்"],[["ORDER",37,"steps",4],"மலைப்பு: TIPP, நிலைப்படுத்தும் பயிற்சி, யாரையாவது அழைத்தல்"],[["ORDER",37,"steps",5],"5 நிமிடம் கழித்து மீண்டும் மதிப்பிடுங்கள்"],[["ORDER",37,"fixes",0,0],"எதுவும் பலன் தரவில்லை"],[["ORDER",37,"fixes",0,1],"இரண்டு கருவிகளைச் சேர்த்துப் பயன்படுத்துங்கள் (நடை + இசை)"],[["ORDER",37,"fixes",1,0],"என் நிலையை நான் கவனிப்பதில்லை"],[["ORDER",37,"fixes",1,1],"சரிபார்க்க ஒரு நாளில் 3 போன் நினைவூட்டல்கள் வையுங்கள்"],[["ORDER",37,"fixes",2,0],"பலன் தருகிறது, ஆனால் நீடிப்பதில்லை"],[["ORDER",37,"fixes",2,1],"ஒவ்வொரு 90 நிமிடத்துக்கும் மீண்டும் செய்யுங்கள்"],[["ORDER",37,"why"],"உடலின் விழிப்பு நிலை உடலைப் பின்பற்றுகிறது: அசைவு, மூச்சு, வெளிச்சம், வெப்பநிலை ஆகியவை அதை நேரடியாக மாற்றும் கருவிகள்."],[["ORDER",37,"simple"],"நீங்கள் எப்படி உணர்கிறீர்களோ அதற்குப் பொருந்தும் கருவியைத் தேர்ந்தெடுங்கள்: மிக வேகமாக இருந்தால் அமைதிப்படுத்துபவை, மிக மந்தமாக இருந்தால் எழுப்பிவிடுபவை."],[["ORDER",38,"t"],"மன மந்தத்தைச் சரிசெய்தல்"],[["ORDER",38,"time"],"10–15 நிமிடம்"],[["ORDER",38,"u"],"மனதில் உள்ள மந்தத்தை நீக்க ஒரு சிறிய வழக்கம்."],[["ORDER",38,"steps",0],"ஒரு பெரிய டம்ளர் தண்ணீர் குடியுங்கள்"],[["ORDER",38,"steps",1],"பகல் வெளிச்சம் படட்டும்: வெளியே போங்கள் அல்லது ஜன்னல் அருகே நில்லுங்கள்"],[["ORDER",38,"steps",2],"5–10 நிமிடம் வேகமாக அசையுங்கள்"],[["ORDER",38,"steps",3],"நீங்கள் சாப்பிடவில்லை என்றால் புரதச்சத்துள்ள ஏதாவது சாப்பிடுங்கள்"],[["ORDER",38,"steps",4],"மீண்டும் தொடங்க ஒரு எளிய வேலையைச் செய்யுங்கள்"],[["ORDER",38,"fixes",0,0],"தினமும் இன்னும் மந்தமாகவே உணர்கிறேன்"],[["ORDER",38,"fixes",0,1],"தூக்கத்தைச் சரிபாருங்கள், மருத்துவரைப் பாருங்கள்"],[["ORDER",38,"fixes",1,0],"காபி உதவுகிறது, ஆனால் பிறகு சோர்ந்துபோகிறேன்"],[["ORDER",38,"fixes",1,1],"எழுந்த பிறகு 60–90 நிமிடம் கழித்துக் காபி குடியுங்கள்"],[["ORDER",38,"fixes",2,0],"நேரமில்லை"],[["ORDER",38,"fixes",2,1],"2 நிமிட அசைவும் தண்ணீரும் கூட உதவும்"],[["ORDER",38,"why"],"தண்ணீர், வெளிச்சம், அசைவு ஆகியவை இரத்த ஓட்டத்தையும் விழிப்பு அமைப்புகளையும் தூண்டி விழிப்புணர்வை அதிகரிக்கின்றன."],[["ORDER",38,"simple"],"மந்தமான மனதைத் தெளிவாக்க, தண்ணீர் குடியுங்கள், வெளியே போங்கள், உடலை அசையுங்கள், ஒரு சிறிய இடைவேளை எடுங்கள்."],[["ORDER",39,"t"],"பெட்டியில் வைக்கும் பயிற்சி (Container Exercise)"],[["ORDER",39,"time"],"5 நிமிடம்"],[["ORDER",39,"u"],"கலக்கமூட்டும் நினைவுகளையோ உணர்வுகளையோ, பாதுகாப்பான ஒரு சூழலில் அவற்றைக் கையாளும் வரை, பத்திரமாக வைத்திருப்பதாகக் கற்பனை செய்யுங்கள்."],[["ORDER",39,"steps",0],"உறுதியான ஒரு பெட்டியைக் கற்பனை செய்யுங்கள் (பெட்டகம், பெட்டி, இரும்புப் பெட்டி)"],[["ORDER",39,"steps",1],"அந்த நினைவையோ உணர்வையோ அதற்குள் வைப்பதாக மனதில் பாருங்கள்"],[["ORDER",39,"steps",2],"அதை மூடிப் பூட்டுங்கள்; அது போய்விடவில்லை, வைத்துவைக்கப்பட்டிருக்கிறது, அவ்வளவுதான்"],[["ORDER",39,"steps",3],"அந்தப் பெட்டியைப் பாதுகாப்பான ஓர் இடத்தில் வையுங்கள்"],[["ORDER",39,"steps",4],"கவனத்தை இப்போதைய நேரத்துக்குத் திருப்புங்கள்"],[["ORDER",39,"fixes",0,0],"பெட்டி மூட மறுக்கிறது"],[["ORDER",39,"fixes",0,1],"அதைப் பெரிதாக்குங்கள் அல்லது இன்னும் உறுதியாக்குங்கள்"],[["ORDER",39,"fixes",1,0],"விஷயங்கள் வெளியே கசிகின்றன"],[["ORDER",39,"fixes",1,1],"இன்னொரு பூட்டு போடுங்கள்; நிலைப்படுத்தும் பயிற்சியைப் பயன்படுத்துங்கள்"],[["ORDER",39,"fixes",2,0],"இது தவிர்ப்பது போல் தோன்றுகிறது"],[["ORDER",39,"fixes",2,1],"இது தற்காலிகமானதுதான்; நீங்கள் தயாராகும்போது சிகிச்சையில் அதைத் திறப்பீர்கள்"],[["ORDER",39,"why"],"அதிர்ச்சிக் காய (ட்ராமா) சிகிச்சையிலிருந்து (EMDR) வரும் ஒரு வலுவூட்டும் திறன்; இது கட்டுப்பாட்டையும் நிலைத்தன்மையையும் வளர்க்கிறது."],[["ORDER",39,"simple"],"ஒரு கவலையை உறுதியான பெட்டிக்குள் வைத்து, பிறகு பாதுகாப்பான ஒருவருடன் சேர்ந்து அதைப் பார்ப்பதாகக் கற்பனை செய்யுங்கள்."],[["ORDER",40,"t"],"உதவி கேட்கும் வார்த்தைகள்"],[["ORDER",40,"time"],"5 நிமிடம்"],[["ORDER",40,"u"],"நீங்கள் போராடும்போது, உறவையோ ஆதரவையோ கேளுங்கள்."],[["ORDER",40,"steps",0],"பாதுகாப்பான ஒரு நபரைத் தேர்ந்தெடுங்கள்"],[["ORDER",40,"steps",1],"ஒரு சிறிய செய்தி அனுப்புங்கள்: “இன்று எனக்குக் கஷ்டமான நாள், 10 நிமிடம் பேச முடியுமா?”"],[["ORDER",40,"steps",2],"அவர் இல்லையென்றால், இன்னொருவரிடம் கேளுங்கள்"],[["ORDER",40,"steps",3],"உங்களுக்குப் பாதுகாப்பாகத் தோன்றும் அளவுக்குப் பகிருங்கள்"],[["ORDER",40,"steps",4],"அவருக்கு நன்றி சொல்லுங்கள்"],[["ORDER",40,"fixes",0,0],"நான் ஒரு பாரமாக இருப்பது போல் உணர்கிறேன்"],[["ORDER",40,"fixes",0,1],"பெரும்பாலானவர்கள் உதவி செய்வதில் மகிழ்ச்சி அடைகிறார்கள்"],[["ORDER",40,"fixes",1,0],"யாரும் கிடைக்கவில்லை"],[["ORDER",40,"fixes",1,1],"உதவி எண்ணை அல்லது ஆதரவுக் குழுவைப் பயன்படுத்துங்கள்"],[["ORDER",40,"fixes",2,0],"தொடங்குவது கடினமாக இருக்கிறது"],[["ORDER",40,"fixes",2,1],"இந்த வார்த்தைகளை அப்படியே பயன்படுத்துங்கள்"],[["ORDER",40,"why"],"உறவின் மூலம் நடக்கும் இணை-அமைதிப்படுத்தல் நரம்பு மண்டலத்தை அமைதிப்படுத்துகிறது."],[["ORDER",40,"simple"],"அன்பான ஒருவருக்குச் செய்தி அனுப்புங்கள்: “எனக்குக் கஷ்டமாக இருக்கிறது. நாம் பேசலாமா?”"],[["ORDER",41,"t"],"படிப்படியாகத் தசைகளைத் தளர்த்துதல்"],[["ORDER",41,"time"],"10–15 நிமிடம்"],[["ORDER",41,"u"],"உடலில் தேங்கியிருக்கும் இறுக்கத்தை விடுவிக்க, தசைக் குழுக்களை இறுக்கித் தளர்த்துங்கள்."],[["ORDER",41,"steps",0],"வசதியாகப் படுத்துக்கொள்ளுங்கள் அல்லது உட்காருங்கள்"],[["ORDER",41,"steps",1],"பாதங்களிலிருந்து தொடங்கி, தசைகளை 5 விநாடிகள் இறுக்குங்கள்"],[["ORDER",41,"steps",2],"10 விநாடிகள் தளர்த்தி, வித்தியாசத்தைக் கவனியுங்கள்"],[["ORDER",41,"steps",3],"மேலே போங்கள்: கெண்டைக்கால், தொடை, வயிறு, கைகள், புஜங்கள், தோள்கள், முகம்"],[["ORDER",41,"steps",4],"மூன்று மெதுவான மூச்சுகளுடன் முடியுங்கள்"],[["ORDER",41,"fixes",0,0],"நான் தூங்கிவிடுகிறேன்"],[["ORDER",41,"fixes",0,1],"படுக்கை நேரத்துக்கு மிகவும் நல்லது; பகலில் உட்கார்ந்து செய்யுங்கள்"],[["ORDER",41,"fixes",1,0],"இறுக்கும்போது வலிக்கிறது"],[["ORDER",41,"fixes",1,1],"பாதி அளவு முயற்சி மட்டும் கொடுங்கள்"],[["ORDER",41,"fixes",2,0],"வரிசையை நினைவில் வைப்பது கடினம்"],[["ORDER",41,"fixes",2,1],"ஒலி வழிகாட்டியைப் பின்பற்றுங்கள்"],[["ORDER",41,"why"],"இறுக்கத்தையும் தளர்வையும் மாறி மாறிச் செய்வது, தளர்வு எப்படி இருக்கும் என்று உடலுக்குக் கற்றுக்கொடுக்கிறது."],[["ORDER",41,"simple"],"ஒரு தசையை இறுக்கிப் பிடித்து, பிறகு தளர விடுங்கள். கால் விரல்களிலிருந்து முகம் வரை இப்படிச் செய்யுங்கள். உங்கள் உடல் ஓய்வெடுக்கக் கற்றுக்கொள்கிறது."],[["ORDER",42,"t"],"உடலை வருடிக் கவனித்தல் (Body Scan)"],[["ORDER",42,"time"],"10 நிமிடம்"],[["ORDER",42,"u"],"உடலுக்குள் நடப்பதை உணரும் திறனை வளர்க்க, கவனத்தை மெதுவாக உடல் முழுவதும் நகர்த்துங்கள்."],[["ORDER",42,"steps",0],"படுத்துக்கொள்ளுங்கள் அல்லது உட்காருங்கள்"],[["ORDER",42,"steps",1],"உள்ளங்கால்களின் மேல் கவனத்தைக் கொண்டுவாருங்கள்"],[["ORDER",42,"steps",2],"குறை சொல்லாமல் உணர்வுகளைக் கவனித்தபடி, மெதுவாக மேலே நகருங்கள்"],[["ORDER",42,"steps",3],"இறுக்கம் தெரிந்தால், அதை நோக்கி மூச்சு விடுங்கள்"],[["ORDER",42,"steps",4],"முழு உடலையும் ஒன்றாக உணர்ந்து முடியுங்கள்"],[["ORDER",42,"fixes",0,0],"சில பகுதிகள் சங்கடமாக இருக்கின்றன"],[["ORDER",42,"fixes",0,1],"அவற்றைத் தவிர்த்துவிடுங்கள் அல்லது கண்களைத் திறந்தே வையுங்கள் (அதிர்ச்சிக் காயத்தைக் கவனத்தில் கொண்டு)"],[["ORDER",42,"fixes",1,0],"எனக்குச் சலிப்பாக இருக்கிறது"],[["ORDER",42,"fixes",1,1],"3 நிமிடமாகக் குறைத்துக்கொள்ளுங்கள்"],[["ORDER",42,"fixes",2,0],"எனக்கு எதுவும் உணரவில்லை"],[["ORDER",42,"fixes",2,1],"சாதாரண உணர்வுகளைக் கவனியுங்கள் (வெப்பநிலை, தொடுதல்)"],[["ORDER",42,"why"],"உடலுக்குள் உணரும் பயிற்சி இன்சுலாவையும் உணர்ச்சி விழிப்புணர்வையும் வலுப்படுத்துகிறது."],[["ORDER",42,"simple"],"தலை முதல் கால் வரை உங்கள் உடலின் ஒவ்வொரு பகுதியையும், எதையும் மாற்றாமல், அன்புடன் மெதுவாகக் கவனியுங்கள்."],[["ORDER",43,"t"],"எண்ணப் பதிவு (CBT)"],[["ORDER",43,"time"],"10–15 நிமிடம்"],[["ORDER",43,"u"],"உதவாத எண்ணங்களைப் பிடியுங்கள், சரிபாருங்கள், மாற்றுங்கள்."],[["ORDER",43,"steps",0],"சூழ்நிலை: என்ன நடந்தது?"],[["ORDER",43,"steps",1],"உணர்வு: அதற்குப் பெயரிட்டு 0–100 அளவில் மதிப்பிடுங்கள்"],[["ORDER",43,"steps",2],"தானாக வந்த எண்ணம்: உங்கள் மனதில் என்ன ஓடியது?"],[["ORDER",43,"steps",3],"ஆதரவான ஆதாரங்களும் எதிரான ஆதாரங்களும்"],[["ORDER",43,"steps",4],"சமநிலையான எண்ணம்: இன்னும் நியாயமான ஒரு கூற்று"],[["ORDER",43,"steps",5],"உணர்வை மீண்டும் மதிப்பிடுங்கள்"],[["ORDER",43,"fixes",0,0],"எதிரான ஆதாரம் எதுவும் கிடைக்கவில்லை"],[["ORDER",43,"fixes",0,1],"கேளுங்கள்: ஒரு நண்பர் என்ன சொல்வார்?"],[["ORDER",43,"fixes",1,0],"சமநிலையான எண்ணம் உண்மையாகத் தோன்றவில்லை"],[["ORDER",43,"fixes",1,1],"அதை இன்னும் அடக்கமாக்குங்கள்"],[["ORDER",43,"fixes",2,0],"வீட்டுப்பாடம் போல் தோன்றுகிறது"],[["ORDER",43,"fixes",2,1],"சிறிய விஷயங்களுக்கு மனதுக்குள்ளேயே செய்யுங்கள்"],[["ORDER",43,"why"],"எண்ணங்களைச் சோதிப்பது முன்மூளைப் புறணியைச் செயல்படுத்தி, தானியங்கி முறைகளைப் பலவீனமாக்குகிறது (Beck)."],[["ORDER",43,"simple"],"ஒரு கவலையான எண்ணத்தை எழுதுங்கள், அதற்கு ஆதரவான, எதிரான ஆதாரங்களைச் சரிபாருங்கள், அன்பான, உண்மையான ஒரு எண்ணத்தைக் கண்டுபிடியுங்கள்."],[["ORDER",44,"t"],"கவலை நேரம்"],[["ORDER",44,"time"],"15 நிமிடம்"],[["ORDER",44,"u"],"கவலைகளை, தினமும் குறித்த ஒரு நேரத்துக்குத் தள்ளிப்போடுங்கள்."],[["ORDER",44,"steps",0],"தினமும் 15 நிமிட நேரத்தைத் தேர்ந்தெடுங்கள் (படுக்கை நேரத்துக்கு அருகில் வேண்டாம்)"],[["ORDER",44,"steps",1],"பகலில், கவலைகளை எழுதிவைத்து “பிறகு” என்று சொல்லுங்கள்"],[["ORDER",44,"steps",2],"கவலை நேரத்தில், பட்டியலைப் பாருங்கள்"],[["ORDER",44,"steps",3],"பிரியுங்கள்: தீர்க்கக்கூடியவை (ஒரு திட்டம் போடுங்கள்) / தீர்க்க முடியாதவை (விட்டுவிடப் பழகுங்கள்)"],[["ORDER",44,"steps",4],"நேரம் முடிந்ததும், நிறுத்துங்கள்"],[["ORDER",44,"fixes",0,0],"கவலைகள் காத்திருக்க மாட்டேன் என்கின்றன"],[["ORDER",44,"fixes",0,1],"அவற்றை எழுதிவைத்து ஒரு நினைவூட்டல் வையுங்கள்"],[["ORDER",44,"fixes",1,0],"கவலை நேரம் எனக்குப் பதட்டத்தைக் கொடுக்கிறது"],[["ORDER",44,"fixes",1,1],"நேரத்தைக் குறைத்து, அமைதிப்படுத்தும் ஒரு செயலுடன் முடியுங்கள்"],[["ORDER",44,"fixes",2,0],"ஒவ்வொரு நாளும் அதே கவலைகள்"],[["ORDER",44,"fixes",2,1],"அவற்றை ஒருமுறை தீர்க்க முயலுங்கள்"],[["ORDER",44,"why"],"தள்ளிப்போடுவது, கவலையைக் கட்டுப்படுத்தவே முடியாது என்ற உணர்வைக் குறைக்கிறது (Borkovec)."],[["ORDER",44,"simple"],"உங்கள் கவலைகளை ஒரு நாளில் ஒரு சிறப்பு 15 நிமிடத்துக்காக வைத்திருங்கள். அந்த நேரத்துக்கு வெளியே, அவற்றிடம் “பிறகு” என்று சொல்லுங்கள்."],[["ORDER",45,"t"],"செயல்பாட்டின் மூலம் மனநிலையை உயர்த்துதல் (Behavioural Activation)"],[["ORDER",45,"time"],"15 நிமிடத் திட்டம்"],[["ORDER",45,"u"],"மனநிலையையும் சக்தியையும் உயர்த்த, மகிழ்ச்சி அல்லது சாதனை உணர்வு தரும் செயல்களுக்கு நேரம் குறியுங்கள்."],[["ORDER",45,"steps",0],"ஒருகாலத்தில் உங்களுக்கு மகிழ்ச்சி அல்லது சாதனை உணர்வு தந்த செயல்களைப் பட்டியலிடுங்கள்"],[["ORDER",45,"steps",1],"இன்றைக்கு அவற்றில் ஒரு சிறிய செயலைத் தேர்ந்தெடுங்கள்"],[["ORDER",45,"steps",2],"நேரத்தையும் இடத்தையும் குறித்து அதைத் திட்டமிடுங்கள்"],[["ORDER",45,"steps",3],"உங்கள் மனநிலை எப்படி இருந்தாலும் அதைச் செய்யுங்கள்"],[["ORDER",45,"steps",4],"முன்பும் பின்பும் மனநிலையை மதிப்பிடுங்கள்"],[["ORDER",45,"fixes",0,0],"எனக்கு எதிலும் மகிழ்ச்சி இல்லை"],[["ORDER",45,"fixes",0,1],"முன்பு உதவிய ஒன்றைத் தேர்ந்தெடுங்கள்; மகிழ்ச்சி பின்னால்தான் வரக்கூடும்"],[["ORDER",45,"fixes",1,0],"நான் திரும்பத் திரும்ப ரத்து செய்கிறேன்"],[["ORDER",45,"fixes",1,1],"அதைச் சிறியதாக்கி, ஒருவருடன் சேர்ந்து செய்யுங்கள்"],[["ORDER",45,"fixes",2,0],"மனநிலை மாறவில்லை"],[["ORDER",45,"fixes",2,1],"ஒரு நாள் அல்ல, ஒரு வாரம் முழுவதும் கவனித்துப் பாருங்கள்"],[["ORDER",45,"why"],"ஊக்கத்துக்கு முன் செயல்: செயல்பாடு வெகுமதிப் பாதைகளை மீண்டும் கட்டியெழுப்புகிறது (மனச்சோர்வுக்கு வலுவான ஆதாரம் உண்டு)."],[["ORDER",45,"simple"],"மனம் தளர்ந்திருக்கும்போது, ஒரு சிறிய மகிழ்ச்சியான செயலையும் ஒரு சிறிய பயனுள்ள செயலையும் திட்டமிடுங்கள். அவற்றைச் செய்வது உங்கள் மனநிலையை உயர்த்தும்."],[["ORDER",46,"t"],"“இப்படி நடந்தால், இதைச் செய்வேன்” திட்டங்கள்"],[["ORDER",46,"time"],"5 நிமிடம்"],[["ORDER",46,"u"],"குறிப்பிட்ட சூழ்நிலைகளில் என்ன செய்வீர்கள் என்று முன்கூட்டியே முடிவு செய்யுங்கள்."],[["ORDER",46,"steps",0],"ஒரு இலக்கையோ பழக்கத்தையோ தேர்ந்தெடுங்கள்"],[["ORDER",46,"steps",1],"ஒரு தூண்டும் அடையாளத்தைக் கண்டுபிடியுங்கள் (நேரம், இடம் அல்லது உணர்வு)"],[["ORDER",46,"steps",2],"எழுதுங்கள்: “[அடையாளம்] நடந்தால், நான் [செயல்] செய்வேன்”"],[["ORDER",46,"steps",3],"செயலைச் சிறியதாக வையுங்கள்"],[["ORDER",46,"steps",4],"வாரந்தோறும் சரிபார்த்து மாற்றியமையுங்கள்"],[["ORDER",46,"fixes",0,0],"திட்டத்தை மறந்துவிடுகிறேன்"],[["ORDER",46,"fixes",0,1],"அந்த இடத்திலேயே ஒட்டும் குறிப்புத் தாளில் எழுதி ஒட்டுங்கள்"],[["ORDER",46,"fixes",1,0],"அந்த அடையாளம் நடப்பதில்லை"],[["ORDER",46,"fixes",1,1],"இன்னும் நம்பகமான ஒரு அடையாளத்தைத் தேர்ந்தெடுங்கள்"],[["ORDER",46,"fixes",2,0],"திட்டங்கள் அதிகமாகிவிட்டன"],[["ORDER",46,"fixes",2,1],"ஒன்றிலிருந்து தொடங்குங்கள்"],[["ORDER",46,"why"],"ஆய்வுகளில், இப்படிச் செயல்படுத்தும் திட்டங்கள் சொன்னதைச் செய்து முடிப்பதை ஏறக்குறைய இரண்டு மடங்காக்குகின்றன (Gollwitzer)."],[["ORDER",46,"simple"],"முன்கூட்டியே முடிவு செய்யுங்கள்: “இது நடந்தால், நான் அதைச் செய்வேன்.” அது நல்ல தேர்வுகளை எளிதாக்குகிறது."],[["ORDER",47,"t"],"ஆழ்ந்த வேலை நேரம்"],[["ORDER",47,"time"],"60–90 நிமிடம்"],[["ORDER",47,"u"],"ஒரு முக்கியமான வேலையில் முழுக் கவனத்துடன் உழைக்க, பாதுகாக்கப்பட்ட ஒரு நேரம்."],[["ORDER",47,"steps",0],"ஒரு வேலையைத் தேர்ந்தெடுத்து, அதன் குறிப்பிட்ட பலனை எழுதுங்கள்"],[["ORDER",47,"steps",1],"உங்கள் நாள்காட்டியில் 60–90 நிமிடத்தை ஒதுக்குங்கள்"],[["ORDER",47,"steps",2],"போனை இன்னொரு அறையில் வையுங்கள், அறிவிப்புகளை அணையுங்கள், டேப்களை மூடுங்கள்"],[["ORDER",47,"steps",3],"2 நிமிட ஆயத்தத்துடன் தொடங்குங்கள்"],[["ORDER",47,"steps",4],"கவனச் சிதறல்களுக்கு ஒரு “பிறகு” பட்டியல் வையுங்கள்"],[["ORDER",47,"steps",5],"அடுத்த படியை எழுதி முடியுங்கள்"],[["ORDER",47,"fixes",0,0],"இடையில் தொந்தரவு வருகிறது"],[["ORDER",47,"fixes",0,1],"மற்றவர்களிடம் சொல்லுங்கள், “தொந்தரவு செய்ய வேண்டாம்” என்ற அட்டையைப் பயன்படுத்துங்கள்"],[["ORDER",47,"fixes",1,0],"அவ்வளவு நேரம் என்னால் கவனம் செலுத்த முடியாது"],[["ORDER",47,"fixes",1,1],"30 நிமிடத்தில் தொடங்கி, படிப்படியாக அதிகரியுங்கள்"],[["ORDER",47,"fixes",2,0],"எனக்கு அமைதியின்மையாக இருக்கிறது"],[["ORDER",47,"fixes",2,1],"2 நிமிடம் அசைந்து இடைவேளை எடுத்து, திரும்பி வாருங்கள்"],[["ORDER",47,"why"],"ஒரே நேரத்தில் ஒரே வேலை செய்வது, கவனம் முந்தைய வேலையில் ஒட்டிக்கொண்டிருப்பதைத் தவிர்க்கிறது (Leroy); கவனம் ஆழமடைய உதவுகிறது."],[["ORDER",47,"simple"],"உங்கள் போனைத் தள்ளி வைத்துவிட்டு, சிறிது நேரம் ஒரே விஷயத்தில் வேலை செய்யுங்கள். அப்படித்தான் உங்கள் மூளை மிகச் சிறப்பாக வேலை செய்கிறது."],[["ORDER",48,"t"],"பொமோடோரோ வேலை ஓட்டங்கள்"],[["ORDER",48,"time"],"25 + 5 நிமிடம்"],[["ORDER",48,"u"],"இடைவேளைகளுடன், நேரம் குறித்த சிறிய ஓட்டங்களாக வேலை செய்யுங்கள்."],[["ORDER",48,"steps",0],"ஒரு வேலையைத் தேர்ந்தெடுங்கள்"],[["ORDER",48,"steps",1],"25 நிமிடத்துக்கு டைமர் வையுங்கள்"],[["ORDER",48,"steps",2],"அந்த வேலையில் மட்டும் கவனம் செலுத்துங்கள்"],[["ORDER",48,"steps",3],"திரைகளை விட்டு விலகி 5 நிமிட இடைவேளை எடுங்கள்"],[["ORDER",48,"steps",4],"நான்கு சுற்றுகளுக்குப் பிறகு, நீண்ட இடைவேளை எடுங்கள்"],[["ORDER",48,"fixes",0,0],"25 நிமிடம் ரொம்ப நீளமாக இருக்கிறது"],[["ORDER",48,"fixes",0,1],"15 நிமிடம் முயலுங்கள்"],[["ORDER",48,"fixes",1,0],"இடைவேளை போனில் ஸ்க்ரோல் செய்வதாக மாறிவிடுகிறது"],[["ORDER",48,"fixes",1,1],"அதற்குப் பதிலாக எழுந்து நின்று, உடலை நீட்டி, தண்ணீர் குடியுங்கள்"],[["ORDER",48,"fixes",2,0],"வேலையில் மூழ்கியிருக்கும்போது டைமர் அதைக் கலைத்துவிடுகிறது"],[["ORDER",48,"fixes",2,1],"டைமரைக் கண்டுகொள்ளாமல் தொடர்ந்து செய்யுங்கள்"],[["ORDER",48,"why"],"நேர எல்லை வைப்பது, தொடங்குவதற்குத் தேவையான முயற்சியைக் குறைத்து, கவனத்தைப் பாதுகாக்கிறது."],[["ORDER",48,"simple"],"25 நிமிடம் வேலை செய்யுங்கள், பிறகு 5 நிமிடம் ஓய்வெடுங்கள். சிறிய ஓட்டங்கள் உங்களைப் புத்துணர்ச்சியுடன் வைக்கின்றன."],[["ORDER",49,"t"],"மூழ்கும் நிலைக்கான (Flow) தயாரிப்புப் பட்டியல்"],[["ORDER",49,"time"],"5 நிமிடத் தயாரிப்பு"],[["ORDER",49,"u"],"மூழ்கும் நிலை (flow) வருவதற்கு வாய்ப்பை அதிகரிக்கும் சூழலை அமைத்துக்கொள்ளுங்கள்."],[["ORDER",49,"steps",0],"இந்த நேரத்துக்கு ஒரு தெளிவான இலக்கை வையுங்கள்"],[["ORDER",49,"steps",1],"கடினத்தன்மையைச் சரிசெய்யுங்கள்: உங்கள் வசதி எல்லைக்குச் சற்று அப்பால்"],[["ORDER",49,"steps",2],"முன்னேற்றத்தை அறிய வழி செய்யுங்கள்: நீங்கள் முன்னேறுகிறீர்கள் என்று எப்படித் தெரிந்துகொள்வீர்கள்?"],[["ORDER",49,"steps",3],"90 நிமிடத்துக்குத் தொந்தரவுகளை நீக்குங்கள்"],[["ORDER",49,"steps",4],"தொடர்புடைய ஒரு எளிய வேலையுடன் ஆயத்தமாகுங்கள்"],[["ORDER",49,"steps",5],"அந்த நேரம் முடிந்ததும் ஓய்வெடுங்கள்"],[["ORDER",49,"fixes",0,0],"இது மிகக் கடினமாக இருக்கிறது, எனக்குப் பதட்டமாகிறது"],[["ORDER",49,"fixes",0,1],"சவாலைக் குறையுங்கள்"],[["ORDER",49,"fixes",1,0],"சலிப்பாக இருக்கிறது"],[["ORDER",49,"fixes",1,1],"சவாலை அதிகரியுங்கள் அல்லது ஒரு நேர வரம்பு வையுங்கள்"],[["ORDER",49,"fixes",2,0],"நான் ஒருபோதும் மூழ்கும் நிலைக்கு வருவதில்லை"],[["ORDER",49,"fixes",2,1],"முதலில் 15–20 நிமிடம் போராட்டம் இருக்கும் என்று எதிர்பாருங்கள்"],[["ORDER",49,"why"],"சவாலும் திறமையும் சமநிலையில் இருக்கும்போது மூழ்கும் நிலை உருவாகிறது (Csikszentmihalyi)."],[["ORDER",49,"simple"],"போதுமான அளவு மட்டும் கடினமான ஒரு வேலை, தெளிவான இலக்குகள், கவனச் சிதறல் இல்லாத சூழல் ஆகியவற்றைத் தேர்ந்தெடுங்கள்; அப்போது நீங்கள் மகிழ்ச்சியாக அதில் மூழ்கிவிடலாம்."],[["ORDER",50,"t"],"தூக்கத்துக்கு முன் அமைதியாகும் வழக்கம்"],[["ORDER",50,"time"],"30–60 நிமிடம்"],[["ORDER",50,"u"],"தூங்கும் நேரம் வந்துவிட்டது என்று மூளைக்குச் சொல்லும், ஒரே மாதிரியான ஒரு வழக்கம்."],[["ORDER",50,"steps",0],"தூங்கும் நேரத்தையும் எழும் நேரத்தையும் ஒழுங்காக வையுங்கள்"],[["ORDER",50,"steps",1],"படுப்பதற்கு ஒரு மணி நேரம் முன்: விளக்குகளை மங்கலாக்குங்கள், திரைகளை அணையுங்கள்"],[["ORDER",50,"steps",2],"கவலைகளை எழுதி மனதைக் காலி செய்யுங்கள்"],[["ORDER",50,"steps",3],"அமைதிப்படுத்தும் ஏதாவது செய்யுங்கள் (வாசித்தல், உடலை நீட்டுதல், ஜெபித்தல், குளித்தல்)"],[["ORDER",50,"steps",4],"20 நிமிடம் தூக்கம் வராவிட்டால், எழுந்து மங்கலான வெளிச்சத்தில் அமைதியான ஏதாவது செய்யுங்கள்"],[["ORDER",50,"fixes",0,0],"என் போனை விட்டுவிட முடியவில்லை"],[["ORDER",50,"fixes",0,1],"அதைப் படுக்கையறைக்கு வெளியே சார்ஜ் செய்யுங்கள்"],[["ORDER",50,"fixes",1,0],"எண்ணங்கள் வேகமாக ஓடுகின்றன"],[["ORDER",50,"fixes",1,1],"மனதைக் காலி செய்யும் எழுத்தையும் மெதுவான மூச்சையும் பயன்படுத்துங்கள்"],[["ORDER",50,"fixes",2,0],"வார இறுதிகள் இதைக் கெடுத்துவிடுகின்றன"],[["ORDER",50,"fixes",2,1],"எழும் நேரம் ஒரு மணி நேரத்துக்கு மேல் மாறாமல் பார்த்துக்கொள்ளுங்கள்"],[["ORDER",50,"why"],"ஒழுங்கான நேரம் உடலின் கடிகாரத்தை நிலைநிறுத்துகிறது; குறைந்த வெளிச்சம் மெலடோனின் வெளிவர உதவுகிறது."],[["ORDER",50,"simple"],"ஒவ்வொரு இரவும் படுப்பதற்கு முன் அதே அமைதியான விஷயங்களைச் செய்யுங்கள்: மங்கலான விளக்கு, திரைகள் இல்லை, ஒரு கதை அல்லது ஜெபம்."],[["ORDER",51,"t"],"பாதுகாப்பான இடத்தைக் கற்பனை செய்தல்"],[["ORDER",51,"time"],"5–10 நிமிடம்"],[["ORDER",51,"u"],"நீங்கள் திரும்பத் திரும்பச் செல்லக்கூடிய, மனதுக்குள் ஒரு அமைதியான இடத்தை உருவாக்குங்கள்."],[["ORDER",51,"steps",0],"நீங்கள் பாதுகாப்பாகவும் அமைதியாகவும் உணரும் ஒரு இடத்தைக் கற்பனை செய்யுங்கள்; அது உண்மையானதாகவோ கற்பனையானதாகவோ இருக்கலாம்"],[["ORDER",51,"steps",1],"புலன் சார்ந்த விவரங்களைச் சேருங்கள்: காட்சிகள், ஒலிகள், மணங்கள், வெப்பநிலை"],[["ORDER",51,"steps",2],"உங்கள் உடலில் எங்கே அமைதியை உணர்கிறீர்கள் என்று கவனியுங்கள்"],[["ORDER",51,"steps",3],"அதற்கு ஒரு குறிச்சொல் கொடுங்கள்"],[["ORDER",51,"steps",4],"தேவைப்படும்போது தயாராக இருக்கும்படி, தினமும் பயிற்சி செய்யுங்கள்"],[["ORDER",51,"fixes",0,0],"பாதுகாப்பான இடம் எதுவும் என் நினைவுக்கு வரவில்லை"],[["ORDER",51,"fixes",0,1],"ஒரு புத்தகத்திலோ படத்திலோ வரும் இடத்தை, அல்லது பாதுகாப்பான ஒரு நபரைக் கற்பனை செய்யுங்கள்"],[["ORDER",51,"fixes",1,0],"கெட்ட நினைவுகள் இடையில் நுழைகின்றன"],[["ORDER",51,"fixes",1,1],"இடத்தை மாற்றுங்கள் அல்லது கண்களைத் திறங்கள்"],[["ORDER",51,"fixes",2,0],"வெறுமையாக இருக்கிறது"],[["ORDER",51,"fixes",2,1],"பாதுகாப்பான ஒரு துணையைச் சேருங்கள்"],[["ORDER",51,"why"],"இப்படி வலுவூட்டுவது, அமைதிப்படுத்துதலுக்கு நங்கூரமாக இருக்கும் நல்ல நினைவுகளின் வலையமைப்பை உருவாக்குகிறது."],[["ORDER",51,"simple"],"கண்களை மூடி, பாதுகாப்பான, அமைதியான ஒரு இடத்தை விரிவாகக் கற்பனை செய்யுங்கள். பயமாக இருக்கும்போது நீங்கள் அங்கே போகலாம்."],[["ORDER",52,"t"],"சிறு ஒளிக்கீற்றுகள் (Glimmers) பயிற்சி"],[["ORDER",52,"time"],"2 நிமிடம்"],[["ORDER",52,"u"],"பாதுகாப்பும் மகிழ்ச்சியும் தரும் சிறிய தருணங்களைக் கவனியுங்கள் (தூண்டுதல்களுக்கு எதிரானவை)."],[["ORDER",52,"steps",0],"இலகுவான சிறிய தருணங்களைத் தேடுங்கள்: சூரிய ஒளி, ஒரு புன்னகை, ஒரு சூடான பானம்"],[["ORDER",52,"steps",1],"அதை உண்மையாகவே கவனிக்க 10 விநாடிகள் நிதானியுங்கள்"],[["ORDER",52,"steps",2],"அதை உங்கள் உடலில் உணருங்கள்"],[["ORDER",52,"steps",3],"ஒரு நாளில் மூன்று ஒளிக்கீற்றுகளை எழுதுங்கள்"],[["ORDER",52,"fixes",0,0],"எனக்கு ஒன்றும் கிடைக்கவில்லை"],[["ORDER",52,"fixes",0,1],"மிகச் சிறிய, சாதாரணமான ஒரு தருணத்திலிருந்து தொடங்குங்கள்"],[["ORDER",52,"fixes",1,0],"வலுக்கட்டாயமாகச் செய்வது போல் தோன்றுகிறது"],[["ORDER",52,"fixes",1,1],"கவனித்தால் மட்டும் போதும், நன்றியுணர்வு வர வேண்டிய அவசியமில்லை"],[["ORDER",52,"fixes",2,0],"மறந்துவிடுகிறேன்"],[["ORDER",52,"fixes",2,1],"ஒரு நினைவூட்டல் வையுங்கள்"],[["ORDER",52,"why"],"நல்ல தருணங்களில் சற்று நேரம் தங்கியிருப்பது, அவை நினைவில் பதிய உதவுகிறது (Hanson சொல்லும் “நல்லதை உள்வாங்குதல்”)."],[["ORDER",52,"simple"],"சூரிய ஒளி அல்லது ஒரு புன்னகை போன்ற சிறிய நல்ல தருணங்களைக் கவனித்து, சில விநாடிகள் அவற்றை அனுபவியுங்கள்."],[["ORDER",53,"t"],"மனநிலைக்காக உடல் அசைவு"],[["ORDER",53,"time"],"20–30 நிமிடம்"],[["ORDER",53,"u"],"மனநிலையைச் சீராக்கவும், மூளை மாறும் திறனை அதிகரிக்கவும் உடல் அசைவைப் பயன்படுத்துங்கள்."],[["ORDER",53,"steps",0],"நீங்கள் ரசிக்கக்கூடிய அசைவைத் தேர்ந்தெடுங்கள் (நடை, நடனம், சைக்கிள்)"],[["ORDER",53,"steps",1],"பெரும்பாலான நாட்களில் 20–30 நிமிடம் செய்ய இலக்கு வையுங்கள்"],[["ORDER",53,"steps",2],"முடிந்தால் வெளியே போங்கள்"],[["ORDER",53,"steps",3],"முன்பும் பின்பும் மனநிலையைக் கவனியுங்கள்"],[["ORDER",53,"fixes",0,0],"எனக்குச் சக்தியே இல்லை"],[["ORDER",53,"fixes",0,1],"5 நிமிடத்தில் தொடங்குங்கள்"],[["ORDER",53,"fixes",1,0],"எனக்கு உடற்பயிற்சி பிடிக்காது"],[["ORDER",53,"fixes",1,1],"ஒரு நண்பருடன் அல்லது ஒரு பாட்காஸ்ட் கேட்டுக்கொண்டு நடங்கள்"],[["ORDER",53,"fixes",2,0],"சில நாட்களைத் தவறவிடுகிறேன்"],[["ORDER",53,"fixes",2,1],"குற்ற உணர்வு இல்லாமல் மீண்டும் தொடங்குங்கள்"],[["ORDER",53,"why"],"ஏரோபிக் உடற்பயிற்சி BDNF-ஐ அதிகரிக்கிறது; இது நரம்பியல் நெகிழ்வுக்கும் (மூளை மாறும் திறன்) மனநிலைக்கும் உதவுகிறது."],[["ORDER",53,"simple"],"நடப்பது, நடனமாடுவது அல்லது விளையாடுவது உங்கள் உடல் நன்றாக உணரவும் மனநிலை உயரவும் உதவுகிறது."],[["ORDER",54,"t"],"பிரச்சினையைத் தீர்க்கும் படிகள்"],[["ORDER",54,"time"],"20 நிமிடம்"],[["ORDER",54,"u"],"உண்மையான பிரச்சினைகளைக் கையாள ஒழுங்கான ஒரு வழி."],[["ORDER",54,"steps",0],"பிரச்சினையைத் தெளிவாக வரையறுங்கள்"],[["ORDER",54,"steps",1],"குறை சொல்லாமல் எல்லா வழிகளையும் யோசியுங்கள்"],[["ORDER",54,"steps",2],"முதல் மூன்று வழிகளின் நன்மை தீமைகளைப் பட்டியலிடுங்கள்"],[["ORDER",54,"steps",3],"ஒன்றைத் தேர்ந்தெடுத்து முதல் படியைத் திட்டமிடுங்கள்"],[["ORDER",54,"steps",4],"அதைச் செய்யுங்கள், பிறகு என்ன நடந்தது என்று பாருங்கள்"],[["ORDER",54,"fixes",0,0],"பிரச்சினைகள் ரொம்ப அதிகம்"],[["ORDER",54,"fixes",0,1],"அதிக மன அழுத்தம் தருவதைத் தேர்ந்தெடுங்கள்"],[["ORDER",54,"fixes",1,0],"நல்ல வழி எதுவும் இல்லை"],[["ORDER",54,"fixes",1,1],"குறைந்த மோசமானதைத் தேர்ந்தெடுத்து, தேவைக்கேற்ப மாற்றுங்கள்"],[["ORDER",54,"fixes",2,0],"நான் செய்து முடிப்பதில்லை"],[["ORDER",54,"fixes",2,1],"“இப்படி நடந்தால், இதைச் செய்வேன்” திட்டத்தைப் பயன்படுத்துங்கள்"],[["ORDER",54,"why"],"ஒழுங்கான முறையில் பிரச்சினைகளைத் தீர்ப்பது கவலையையும் உதவியற்ற உணர்வையும் குறைக்கிறது."],[["ORDER",54,"simple"],"பிரச்சினைக்குப் பெயரிடுங்கள், யோசனைகளைச் சிந்தியுங்கள், ஒன்றைத் தேர்ந்தெடுங்கள், அதைச் செய்து பார்த்து, எப்படிப் போகிறது என்று கவனியுங்கள்."],[["ORDER",55,"t"],"பய ஏணி (படிப்படியாக எதிர்கொள்ளுதல்)"],[["ORDER",55,"time"],"சில வாரங்கள்"],[["ORDER",55,"u"],"பயங்களைப் படிப்படியாக எதிர்கொள்ளுங்கள்; அப்போது அவை பாதுகாப்பானவை என்று மூளை கற்றுக்கொள்கிறது."],[["ORDER",55,"steps",0],"நீங்கள் தவிர்க்கும் சூழ்நிலைகளைப் பட்டியலிட்டு, பயத்தை 0–10 அளவில் மதிப்பிடுங்கள்"],[["ORDER",55,"steps",1],"எளிதானதிலிருந்து கடினமானது வரை வரிசைப்படுத்துங்கள்"],[["ORDER",55,"steps",2],"3–4 அளவுள்ள ஒரு படியிலிருந்து தொடங்குங்கள்"],[["ORDER",55,"steps",3],"பயம் ஏறக்குறைய பாதியாகக் குறையும் வரை அதில் இருங்கள் (பாதுகாப்புக்காகச் செய்யும் பழக்கங்கள் இல்லாமல்)"],[["ORDER",55,"steps",4],"எளிதாகும் வரை திரும்பத் திரும்பச் செய்யுங்கள், பிறகு அடுத்த படிக்குப் போங்கள்"],[["ORDER",55,"fixes",0,0],"பயம் குறைவதில்லை"],[["ORDER",55,"fixes",0,1],"இன்னும் கொஞ்ச நேரம் இருங்கள் அல்லது எளிதான ஒரு படியைத் தேர்ந்தெடுங்கள்"],[["ORDER",55,"fixes",1,0],"பாதுகாப்புக்கான பழக்கங்களைப் பயன்படுத்துகிறேன்"],[["ORDER",55,"fixes",1,1],"அவற்றை ஒவ்வொன்றாக விட்டுவிடுங்கள்"],[["ORDER",55,"fixes",2,0],"படிகளைத் தாண்டிவிடுகிறேன்"],[["ORDER",55,"fixes",2,1],"மெதுவாகப் போங்கள்; வேகத்தைவிட தொடர்ச்சியே முக்கியம்"],[["ORDER",55,"why"],"எதிர்கொள்ளுதல் புதிய பாதுகாப்புக் கற்றலை உருவாக்குகிறது; அது பய நினைவுடன் போட்டியிடுகிறது (inhibitory learning – தடுக்கும் கற்றல்)."],[["ORDER",55,"simple"],"பயமுறுத்தும் விஷயங்களைச் சிறியதிலிருந்து பெரியது வரை ஒரு ஏணியாக அமையுங்கள். ஒவ்வொன்றும் சரியாகத் தோன்றும் வரை ஒவ்வொரு படியாக ஏறுங்கள்."],[["ORDER",56,"t"],"இரக்கமுள்ள கடிதம்"],[["ORDER",56,"time"],"20 நிமிடம்"],[["ORDER",56,"u"],"இரக்கமுள்ள ஒரு நண்பரின் பார்வையிலிருந்து உங்களுக்கே எழுதுங்கள்."],[["ORDER",56,"steps",0],"நீங்கள் உங்களையே குறை சொல்லும் ஒரு விஷயத்தை நினைத்துப் பாருங்கள்"],[["ORDER",56,"steps",1],"உங்களை முழுமையாக அறிந்த, ஞானமும் அன்பும் உள்ள ஒரு நண்பரைக் கற்பனை செய்யுங்கள்"],[["ORDER",56,"steps",2],"அவர் உங்களுக்கு எழுதுவது போல ஒரு கடிதம் எழுதுங்கள்"],[["ORDER",56,"steps",3],"புரிதல், அன்பு, ஊக்கம் ஆகியவற்றைச் சேருங்கள்"],[["ORDER",56,"steps",4],"பிறகு அதைச் சத்தமாக வாசியுங்கள்"],[["ORDER",56,"fixes",0,0],"அன்பை என்னால் கற்பனை செய்ய முடியவில்லை"],[["ORDER",56,"fixes",0,1],"உங்களுக்குத் தெரிந்த ஒருவரை அல்லது ஒரு ஆன்மீக நபரைப் பயன்படுத்துங்கள்"],[["ORDER",56,"fixes",1,0],"இது உண்மையற்றதாகத் தோன்றுகிறது"],[["ORDER",56,"fixes",1,1],"நேர்மையாக எழுதுங்கள்; அன்பு என்பது உண்மையை மறுப்பது அல்ல"],[["ORDER",56,"fixes",2,0],"இது வலியை மேலே கொண்டுவருகிறது"],[["ORDER",56,"fixes",2,1],"மென்மையாகச் செய்யுங்கள்; பிறகு நிலைப்படுத்தும் பயிற்சியைப் பயன்படுத்துங்கள்"],[["ORDER",56,"why"],"ஆறுதல் அமைப்பைச் செயல்படுத்தி, தன்னுடன் பேசும் புதிய வழிகளை உருவாக்குகிறது (CFT)."],[["ORDER",56,"simple"],"ஒரு அன்பான நண்பரிடமிருந்தோ தேவனிடமிருந்தோ வருவது போல, உங்களுக்கே ஒரு கடிதம் எழுதுங்கள்."],[["ORDER",57,"t"],"உள் விமர்சகருக்குப் பதில் சொல்லுதல்"],[["ORDER",57,"time"],"15 நிமிடம்"],[["ORDER",57,"u"],"உள் விமர்சகருக்குக் கீழ்ப்படியாமல், அதை அடையாளம் கண்டு பதில் சொல்லுங்கள்."],[["ORDER",57,"steps",0],"விமர்சகர் சொல்லும் அதே வார்த்தைகளை எழுதுங்கள்"],[["ORDER",57,"steps",1],"அது யாருடைய குரல் போல ஒலிக்கிறது என்று கவனியுங்கள்"],[["ORDER",57,"steps",2],"கேளுங்கள்: அது என்னை எதிலிருந்து பாதுகாக்க முயல்கிறது?"],[["ORDER",57,"steps",3],"ஞானமும் அன்பும் உள்ள உங்கள் உள்ளத்திலிருந்து ஒரு பதிலை எழுதுங்கள்"],[["ORDER",57,"steps",4],"அந்தப் பதிலைச் சத்தமாகச் சொல்லிப் பழகுங்கள்"],[["ORDER",57,"fixes",0,0],"விமர்சகரின் குரல் அதிகச் சத்தமாக இருக்கிறது"],[["ORDER",57,"fixes",0,1],"எதிர்பார்ப்புகளைக் குறைத்துக்கொள்ளுங்கள்; அதைக் கவனித்தால் மட்டும் போதும்"],[["ORDER",57,"fixes",1,0],"நான் விமர்சகருடன் ஒத்துப்போகிறேன்"],[["ORDER",57,"fixes",1,1],"ஒரு நண்பர் என்ன சொல்வார் என்று கேளுங்கள்"],[["ORDER",57,"fixes",2,0],"இது இன்னும் மோசமாகிறது"],[["ORDER",57,"fixes",2,1],"ஒரு சிகிச்சையாளரின் உதவியை நாடுங்கள்"],[["ORDER",57,"why"],"விமர்சகருடன் உங்களுக்குள்ள உறவை மாற்றுவது, தன்னுடன் பேசும் மாற்று வழிகளை உருவாக்குகிறது."],[["ORDER",57,"simple"],"உங்கள் தலைக்குள் இருக்கும் கடுமையான குரல் பேசும்போது, அன்பான ஒரு பயிற்சியாளர் பதில் சொல்வது போல அதற்குப் பதில் சொல்லுங்கள்."],[["ORDER",58,"t"],"DEAR MAN: உறுதியாகக் கேட்பது"],[["ORDER",58,"time"],"10 நிமிடத் தயாரிப்பு"],[["ORDER",58,"u"],"உங்களுக்குத் தேவையானதைக் கேட்க உதவும் ஒரு DBT வழிமுறை."],[["ORDER",58,"steps",0],"உண்மைகளை விவரியுங்கள் (Describe)"],[["ORDER",58,"steps",1],"உங்கள் உணர்வுகளை வெளிப்படுத்துங்கள் (Express) (“நான் … உணர்கிறேன்”)"],[["ORDER",58,"steps",2],"உங்கள் கோரிக்கையைத் தெளிவாக உறுதியுடன் சொல்லுங்கள் (Assert)"],[["ORDER",58,"steps",3],"வலுப்படுத்துங்கள் (Reinforce): நன்மைகளை விளக்குங்கள்"],[["ORDER",58,"steps",4],"கவனத்துடன் இருங்கள் (Mindful): உங்கள் கருத்திலேயே நில்லுங்கள்"],[["ORDER",58,"steps",5],"தன்னம்பிக்கையுடன் தோன்றுங்கள் (Appear confident): நிதானமான குரல்"],[["ORDER",58,"steps",6],"பேச்சுவார்த்தை செய்யுங்கள் (Negotiate): கொஞ்சம் விட்டுக்கொடுக்கத் தயாராக இருங்கள்"],[["ORDER",58,"fixes",0,0],"நான் தடுமாறிவிடுகிறேன்"],[["ORDER",58,"fixes",0,1],"வார்த்தைகளை எழுதி, சத்தமாகச் சொல்லிப் பழகுங்கள்"],[["ORDER",58,"fixes",1,0],"அவர்கள் வாதாடுகிறார்கள்"],[["ORDER",58,"fixes",1,1],"உங்கள் கோரிக்கையை அமைதியாகத் திரும்பத் திரும்பச் சொல்லுங்கள் (“உடைந்த ரெக்கார்டு” போல)"],[["ORDER",58,"fixes",2,0],"நான் விட்டுக்கொடுத்துவிடுகிறேன்"],[["ORDER",58,"fixes",2,1],"எதுவரை விட்டுக்கொடுக்கலாம் என்ற எல்லையை முன்கூட்டியே முடிவு செய்யுங்கள்"],[["ORDER",58,"why"],"தெளிவான அமைப்பு பதட்டத்தைக் குறைத்து, பலனை அதிகரிக்கிறது (Linehan)."],[["ORDER",58,"simple"],"ஒன்றைக் கேட்கும் ஒரு வழி: நடந்ததை விவரியுங்கள், எப்படி உணர்கிறீர்கள் என்று சொல்லுங்கள், தெளிவாகக் கேளுங்கள், அது ஏன் உதவும் என்று விளக்குங்கள், அமைதியாக இருங்கள்."],[["ORDER",59,"t"],"எல்லை வார்த்தைகள்"],[["ORDER",59,"time"],"10 நிமிடத் தயாரிப்பு"],[["ORDER",59,"u"],"தெளிவான, அன்பான ஒரு எல்லையை வையுங்கள்."],[["ORDER",59,"steps",0],"நடத்தைக்குப் பெயரிடுங்கள்: “நீங்கள் … செய்யும்போது”"],[["ORDER",59,"steps",1],"உங்கள் உணர்வைச் சொல்லுங்கள்: “நான் … உணர்கிறேன்”"],[["ORDER",59,"steps",2],"எல்லையைச் சொல்லுங்கள்: “என்னால் … முடியாது / எனக்கு … தேவை”"],[["ORDER",59,"steps",3],"நீங்கள் என்ன செய்வீர்கள் என்று சொல்லுங்கள்: “மீண்டும் இப்படி நடந்தால், நான் …”"],[["ORDER",59,"steps",4],"சொன்னதைச் செய்யுங்கள்"],[["ORDER",59,"fixes",0,0],"எனக்குக் குற்ற உணர்வாக இருக்கிறது"],[["ORDER",59,"fixes",0,1],"குற்ற உணர்வு நீங்கள் தவறு செய்தீர்கள் என்பதற்கு ஆதாரம் அல்ல"],[["ORDER",59,"fixes",1,0],"அவர்கள் எதிர்க்கிறார்கள்"],[["ORDER",59,"fixes",1,1],"எல்லையை அமைதியாகத் திரும்பச் சொல்லுங்கள்"],[["ORDER",59,"fixes",2,0],"நான் சொன்னதைச் செய்வதில்லை"],[["ORDER",59,"fixes",2,1],"உங்களால் கடைப்பிடிக்க முடிந்த ஒரு விளைவைத் தேர்ந்தெடுங்கள்"],[["ORDER",59,"why"],"தொடர்ந்து ஒரே மாதிரி நடந்துகொள்வது மற்றவர்களுக்குக் கற்றுக்கொடுக்கிறது; மோதல் பற்றிய உங்கள் சொந்தப் பயத்தையும் மாற்றியமைக்கிறது."],[["ORDER",59,"simple"],"அன்பாகவும் தெளிவாகவும் “முடியாது” என்று சொல்லும் வார்த்தைகள்: “என்னால் அதைச் செய்ய முடியாது, ஆனால் என்னால் … முடியும்”"],[["ORDER",60,"t"],"உறவைச் சரிசெய்யும் உரையாடல்"],[["ORDER",60,"time"],"20 நிமிடம்"],[["ORDER",60,"u"],"ஒரு சண்டைக்குப் பிறகு மீண்டும் இணையுங்கள்."],[["ORDER",60,"steps",0],"இருவரும் அமைதியாகும் வரை காத்திருங்கள்"],[["ORDER",60,"steps",1],"உங்கள் பக்கத்திலிருந்து என்ன நடந்தது என்று சொல்லுங்கள்"],[["ORDER",60,"steps",2],"சாக்குப்போக்கு இல்லாமல் உங்கள் பங்கை ஏற்றுக்கொள்ளுங்கள்"],[["ORDER",60,"steps",3],"அது அவர்களை எப்படிப் பாதித்தது என்று கேட்டு, கவனித்துக் கேளுங்கள்"],[["ORDER",60,"steps",4],"ஒரு மாற்றத்துக்கு ஒப்புக்கொள்ளுங்கள்"],[["ORDER",60,"steps",5],"மீண்டும் இணையுங்கள்: ஒரு அணைப்பு, ஒரு அன்பான வார்த்தை, ஒன்றாகச் செலவிடும் நேரம்"],[["ORDER",60,"fixes",0,0],"அவர்கள் இன்னும் தயாராக இல்லை"],[["ORDER",60,"fixes",0,1],"இடம் கொடுங்கள், பிறகு மீண்டும் முன்வாருங்கள்"],[["ORDER",60,"fixes",1,0],"நான் என்னைத் தற்காத்துக்கொள்ள முயல்கிறேன்"],[["ORDER",60,"fixes",1,1],"உங்கள் பங்கில் மட்டும் கவனம் செலுத்துங்கள்"],[["ORDER",60,"fixes",2,0],"இது மீண்டும் நடக்கிறது"],[["ORDER",60,"fixes",2,1],"மீண்டும் சரிசெய்யுங்கள்; பழக்க முறைகள் மெதுவாகத்தான் மாறும்"],[["ORDER",60,"why"],"உறவு உடைவதும் மீண்டும் சரிசெய்யப்படுவதும் பாதுகாப்பான பிணைப்பையும் நம்பிக்கையையும் வளர்க்கிறது."],[["ORDER",60,"simple"],"ஒரு சண்டைக்குப் பிறகு, உங்கள் பங்குக்கு மன்னிப்புக் கேளுங்கள், கவனித்துக் கேளுங்கள், மீண்டும் ஒன்றாக முயலுங்கள்."],[["ORDER",61,"t"],"பழக்கத்தை மாற்றிவைத்தல்"],[["ORDER",61,"time"],"2–4 வாரங்கள்"],[["ORDER",61,"u"],"தூண்டும் அடையாளத்தையும் வெகுமதியையும் அப்படியே வைத்து, செயல்முறையை மட்டும் மாற்றி, ஒரு பழக்கத்தை மாற்றுங்கள்."],[["ORDER",61,"steps",0],"ஒரு வாரத்துக்குப் பழக்கத்தைக் கவனித்துக் குறியுங்கள்: அடையாளம், செயல்முறை, வெகுமதி"],[["ORDER",61,"steps",1],"உண்மையான வெகுமதியைக் கண்டுபிடியுங்கள் (நிம்மதி, உறவு, உற்சாகம்)"],[["ORDER",61,"steps",2],"அதே போன்ற வெகுமதி தரும் ஒரு புதிய செயல்முறையைத் தேர்ந்தெடுங்கள்"],[["ORDER",61,"steps",3],"அதை எளிதாகவும் கண்ணில் படும்படியும் வையுங்கள்"],[["ORDER",61,"steps",4],"தினமும் செய்யுங்கள்; இடையில் தவறுவது இயல்பு என்று எதிர்பாருங்கள்"],[["ORDER",61,"fixes",0,0],"நான் பழையபடி திரும்பிவிடுகிறேன்"],[["ORDER",61,"fixes",0,1],"அந்த அடையாளத்தைக் குறித்துக்கொண்டு மாற்றியமையுங்கள்"],[["ORDER",61,"fixes",1,0],"புதிய செயல்முறை திருப்தி தரவில்லை"],[["ORDER",61,"fixes",1,1],"வேறொன்றை முயலுங்கள்"],[["ORDER",61,"fixes",2,0],"பழக்கங்கள் ரொம்ப அதிகம்"],[["ORDER",61,"fixes",2,1],"ஒன்றிலிருந்து தொடங்குங்கள்"],[["ORDER",61,"why"],"பழக்கங்கள் “அடையாளம்–செயல்முறை–வெகுமதி” சுழற்சிகளில் வாழ்கின்றன; செயல்முறையை மாற்றும்போது அந்தச் சுழற்சி மாற்றியமைக்கப்படுகிறது (Duhigg; Graybiel)."],[["ORDER",61,"simple"],"ஒரு பழக்கத்தை நினைவூட்டும் விஷயத்தை அப்படியே வைத்துக்கொண்டு, புதிய, நல்ல ஒரு செயலை மாற்றாக வையுங்கள்."],[["ORDER",62,"t"],"உங்கள் உள்ளிருக்கும் குழந்தையுடன் பெற்றோர் போல் பேசுதல்"],[["ORDER",62,"time"],"15 நிமிடம்"],[["ORDER",62,"u"],"சிறு வயதில் உங்களுக்குக் கிடைக்காத அக்கறையை, உங்கள் இளைய உள்ளத்துக்குக் கொடுங்கள்."],[["ORDER",62,"steps",0],"குழந்தைப் பருவத்தில் எடுத்த உங்கள் புகைப்படத்தைத் தேடுங்கள், அல்லது சிறு வயது உங்களைக் கற்பனை செய்யுங்கள்"],[["ORDER",62,"steps",1],"அந்தக் குழந்தை என்ன உணர்கிறது என்று கவனியுங்கள்"],[["ORDER",62,"steps",2],"கேளுங்கள்: இப்போது உனக்கு என்ன தேவை?"],[["ORDER",62,"steps",3],"அன்பான பெற்றோர் போல் பதில் சொல்லுங்கள்: “நீ பாதுகாப்பாக இருக்கிறாய், நான் இங்கே இருக்கிறேன்”"],[["ORDER",62,"steps",4],"இன்று ஒரு அக்கறைச் செயலைச் செய்யுங்கள்"],[["ORDER",62,"fixes",0,0],"இது அசட்டுத்தனமாகத் தோன்றுகிறது"],[["ORDER",62,"fixes",0,1],"பேசுவதற்குப் பதிலாக எழுதிப் பாருங்கள்"],[["ORDER",62,"fixes",1,0],"இது மலைப்பாக இருக்கிறது"],[["ORDER",62,"fixes",1,1],"சுருக்கமாக வைத்து, பிறகு நிலைப்படுத்தும் பயிற்சி செய்யுங்கள்"],[["ORDER",62,"fixes",2,0],"அந்தக் குழந்தை மேல் எனக்குக் கோபம் வருகிறது"],[["ORDER",62,"fixes",2,1],"அந்த விமர்சகரைக் கவனித்து, மென்மையாக அதை ஒதுக்கி வையுங்கள்"],[["ORDER",62,"why"],"இரக்கமுள்ள கற்பனை ஆறுதல் அமைப்பைச் செயல்படுத்தி, பழைய உணர்ச்சிக் கற்றலைப் புதுப்பிக்கிறது."],[["ORDER",62,"simple"],"உங்களுக்குள் இருக்கும் சிறு குழந்தையிடம் அன்பாகப் பேசி, அதற்குத் தேவைப்பட்ட ஆறுதலைக் கொடுங்கள்."],[["ORDER",63,"t"],"புலம்பல் எழுதுதல்"],[["ORDER",63,"time"],"20 நிமிடம்"],[["ORDER",63,"u"],"வேதாகமப் புலம்பல்களின் அமைப்பைப் பின்பற்றி, உங்கள் வலியை நேர்மையாக வெளிப்படுத்துங்கள்."],[["ORDER",63,"steps",0],"அழைத்தல்: தேவனிடம் பேசுங்கள் (அல்லது புரிந்துகொள்ளும் அவருக்கு எழுதுங்கள்)"],[["ORDER",63,"steps",1],"முறையிடுதல்: வலிக்கு நேர்மையாகப் பெயரிடுங்கள்"],[["ORDER",63,"steps",2],"வேண்டுதல்: உங்களுக்குத் தேவையானதைக் கேளுங்கள்"],[["ORDER",63,"steps",3],"நம்பிக்கை: சிறியதாக இருந்தாலும், உங்களால் முடிந்த நம்பிக்கையை வெளிப்படுத்துங்கள்"],[["ORDER",63,"steps",4],"துதி அல்லது எதிர்பார்ப்பு: நீங்கள் பற்றிக்கொண்டிருப்பதைச் சொல்லி முடியுங்கள்"],[["ORDER",63,"fixes",0,0],"நம்பிக்கை வைக்க எதுவும் கிடைக்கவில்லை"],[["ORDER",63,"fixes",0,1],"அதை வெறுமையாக விடுங்கள்; நேர்மையே போதும்"],[["ORDER",63,"fixes",1,0],"இது மரியாதைக் குறைவாகத் தோன்றுகிறது"],[["ORDER",63,"fixes",1,1],"பல சங்கீதங்கள் மிக வெளிப்படையாக, பச்சையாகப் பேசுகின்றன"],[["ORDER",63,"fixes",2,0],"இன்னும் மோசமாக உணர்கிறேன்"],[["ORDER",63,"fixes",2,1],"நிலைப்படுத்தும் பயிற்சி செய்து, யாரிடமாவது அதைப் பகிருங்கள்"],[["ORDER",63,"why"],"உணர்வுகளை எழுதி வெளிப்படுத்துவது மன அழுத்தத்தைக் குறைத்து, வலியான அனுபவங்களை மனதுக்குள் ஒருங்கிணைக்க உதவுகிறது (Pennebaker)."],[["ORDER",63,"simple"],"உங்களைக் காயப்படுத்துவதைப் பற்றி தேவனிடம் நேர்மையாக எழுதுங்கள், பிறகு அவர் உங்களோடு இருக்கிறார் என்பதை நினைவுகூருங்கள்."],[["ORDER",64,"t"],"மதிப்பீட்டுத் திசைகாட்டி"],[["ORDER",64,"time"],"30 நிமிடம்"],[["ORDER",64,"u"],"உங்களுக்கு மிக முக்கியமானது எது என்று கண்டுபிடித்து, தேர்வுகளை வழிநடத்த அதைப் பயன்படுத்துங்கள்."],[["ORDER",64,"steps",0],"உங்களுக்கு முக்கியமான 10 மதிப்பீடுகளைப் பட்டியலிடுங்கள்"],[["ORDER",64,"steps",1],"அவற்றை 5 ஆக, பிறகு 3 ஆகக் குறையுங்கள்"],[["ORDER",64,"steps",2],"ஒவ்வொன்றையும் எவ்வளவு வாழ்ந்து காட்டுகிறீர்கள் என்று மதிப்பிடுங்கள் (0–10)"],[["ORDER",64,"steps",3],"இந்த வாரம் ஒவ்வொரு மதிப்பீட்டுக்கும் ஒரு சிறிய செயலைத் தேர்ந்தெடுங்கள்"],[["ORDER",64,"steps",4],"வாரந்தோறும் சரிபாருங்கள்"],[["ORDER",64,"fixes",0,0],"எல்லாமே முக்கியமாகத் தெரிகிறது"],[["ORDER",64,"fixes",0,1],"உங்கள் 80-வது பிறந்தநாளில் உங்களைப் பற்றி என்ன சொல்லப்பட வேண்டும் என்று விரும்புவீர்கள் என்று கேளுங்கள்"],[["ORDER",64,"fixes",1,0],"மதிப்பீடுகள் ஒன்றோடொன்று மோதுகின்றன"],[["ORDER",64,"fixes",1,1],"என்றைக்கும் அல்ல, இந்தக் காலகட்டத்துக்காகத் தேர்ந்தெடுங்கள்"],[["ORDER",64,"fixes",2,0],"அவற்றின்படி நான் செயல்படுவதில்லை"],[["ORDER",64,"fixes",2,1],"“இப்படி நடந்தால், இதைச் செய்வேன்” திட்டங்களைப் பயன்படுத்துங்கள்"],[["ORDER",64,"why"],"மதிப்பீடுகளால் வழிநடத்தப்படும் செயல், வாழ்க்கைக்கு அர்த்தத்தையும் மனதின் நெகிழ்வுத்தன்மையையும் அதிகரிக்கிறது (ACT)."],[["ORDER",64,"simple"],"உங்களுக்கு மிக முக்கியமானது எது என்று கண்டுபிடித்து, ஒவ்வொரு நாளும் அதை நோக்கி ஒரு சிறிய அடி எடுத்து வையுங்கள்."],[["ORDER",65,"t"],"வாராந்திர மீளாய்வு & முன்னேற்றப் பதிவு"],[["ORDER",65,"time"],"20 நிமிடம்"],[["ORDER",65,"u"],"முன்னேற்றத்தைக் கவனித்து, அடுத்த வாரத்தைத் திட்டமிடுங்கள்."],[["ORDER",65,"steps",0],"வாரத்தைத் திரும்பிப் பாருங்கள்: எது நன்றாக நடந்தது?"],[["ORDER",65,"steps",1],"எது கடினமாக இருந்தது?"],[["ORDER",65,"steps",2],"என் பழக்க முறைகளைப் பற்றி நான் என்ன கற்றுக்கொண்டேன்?"],[["ORDER",65,"steps",3],"ஒரு வெற்றியைக் கொண்டாடுங்கள்"],[["ORDER",65,"steps",4],"அடுத்த வாரத்துக்கு மூன்று முன்னுரிமைகளைத் திட்டமிடுங்கள்"],[["ORDER",65,"fixes",0,0],"நான் இதைத் தவிர்த்துவிடுகிறேன்"],[["ORDER",65,"fixes",0,1],"ஒவ்வொரு வாரமும் அதே நேரத்தில் இதற்கு நேரம் குறியுங்கள்"],[["ORDER",65,"fixes",1,0],"எனக்குத் தோல்விகள் மட்டுமே தெரிகின்றன"],[["ORDER",65,"fixes",1,1],"முதலில் மூன்று வெற்றிகளைப் பட்டியலிடுங்கள்"],[["ORDER",65,"fixes",2,0],"இது ரொம்ப நேரம் எடுக்கிறது"],[["ORDER",65,"fixes",2,1],"ஒவ்வொரு முறையும் அதே 5 கேள்விகளைப் பயன்படுத்துங்கள்"],[["ORDER",65,"why"],"முன்னேற்றத்தைக் கவனிப்பது ஊக்கத்தைத் தக்கவைத்து, கற்றதை உறுதிப்படுத்துகிறது."],[["ORDER",65,"simple"],"வாரத்துக்கு ஒருமுறை, எது நன்றாக நடந்தது, என்ன கற்றுக்கொண்டீர்கள் என்று திரும்பிப் பாருங்கள்."],[["ORDER",66,"t"],"மன்னிக்கும் செயல்முறை"],[["ORDER",66,"time"],"சில வாரங்கள்"],[["ORDER",66,"u"],"பாதுகாப்பைக் காத்துக்கொண்டே, மனக்கசப்பை விடுவிக்கும் படிப்படியான ஒரு பாதை."],[["ORDER",66,"steps",0],"ஏற்பட்ட காயத்தையும் அதன் பாதிப்பையும் முழுமையாகப் பெயரிட்டுச் சொல்லுங்கள்"],[["ORDER",66,"steps",1],"கோபத்தையும் துக்கத்தையும் உணருங்கள், அவற்றைத் தவிர்க்காதீர்கள்"],[["ORDER",66,"steps",2],"கடனை விட்டுவிட முடிவு செய்யுங்கள் (இது ஒரு தேர்வு, ஒரு உணர்வு அல்ல)"],[["ORDER",66,"steps",3],"தேவையான இடங்களில் எல்லைகளைக் காத்துக்கொள்ளுங்கள்"],[["ORDER",66,"steps",4],"காயம் மீண்டும் வலிக்கும்போது திரும்பவும் செய்யுங்கள்"],[["ORDER",66,"fixes",0,0],"என்னால் இன்னும் மன்னிக்க முடியவில்லை"],[["ORDER",66,"fixes",0,1],"பரவாயில்லை; மன்னிக்க விருப்பம் கொள்ள விருப்பப்படுவதிலிருந்து தொடங்குங்கள்"],[["ORDER",66,"fixes",1,0],"அவர்கள் வருந்தவில்லை"],[["ORDER",66,"fixes",1,1],"மன்னிப்புக்கு அவர்கள் மன்னிப்புக் கேட்க வேண்டிய அவசியமில்லை"],[["ORDER",66,"fixes",2,0],"இது அவர்களை நியாயப்படுத்துவது போல் தோன்றுகிறது"],[["ORDER",66,"fixes",2,1],"மன்னிப்பு தவறைத் தவறு என்றே சொல்கிறது"],[["ORDER",66,"why"],"மன்னிப்பு சார்ந்த சிகிச்சை முறைகள் கோபம், பதட்டம், மனச்சோர்வு ஆகியவற்றைக் குறைக்கின்றன (Worthington, Enright)."],[["ORDER",66,"simple"],"மன்னிப்பதற்கு நேரம் எடுக்கும். காயத்துக்குப் பெயரிடுங்கள், அதைத் தேவனிடம் ஒப்படையுங்கள், படிப்படியாக விட்டுவிடத் தேர்ந்தெடுங்கள்."],[["ORDER",67,"t"],"உங்கள் வாழ்க்கைக் கதையை அத்தியாயங்களாக எழுதுதல்"],[["ORDER",67,"time"],"30 நிமிடம்"],[["ORDER",67,"u"],"கடந்த காலத்தை ஒருங்கிணைக்க, உங்கள் வாழ்க்கைக் கதையைப் புரிந்துகொள்ளுங்கள்."],[["ORDER",67,"steps",0],"உங்கள் வாழ்க்கையை அத்தியாயங்களாகப் பிரியுங்கள்"],[["ORDER",67,"steps",1],"ஒவ்வொரு அத்தியாயத்துக்கும் ஒரு தலைப்பு கொடுங்கள்"],[["ORDER",67,"steps",2],"முக்கிய நிகழ்வுகள், உணர்வுகள், பாடங்களை எழுதுங்கள்"],[["ORDER",67,"steps",3],"பலங்களையும் திருப்புமுனைகளையும் கவனியுங்கள்"],[["ORDER",67,"steps",4],"அடுத்த அத்தியாயத்தின் தலைப்பை எழுதுங்கள்"],[["ORDER",67,"fixes",0,0],"இது ரொம்ப அதிகமான நினைவுகளைக் கிளறுகிறது"],[["ORDER",67,"fixes",0,1],"ஆதரவுடன், ஒரு நேரத்தில் ஒரு அத்தியாயம் மட்டும் எழுதுங்கள்"],[["ORDER",67,"fixes",1,0],"எனக்கு நினைவில்லை"],[["ORDER",67,"fixes",1,1],"உங்களுக்கு நினைவில் இருப்பதை எழுதுங்கள்"],[["ORDER",67,"fixes",2,0],"இது எதிர்மறையாகத் தோன்றுகிறது"],[["ORDER",67,"fixes",2,1],"“நான் தாங்கிப் பிழைக்க எது உதவியது” என்பதைச் சேருங்கள்"],[["ORDER",67,"why"],"தெளிவாக இணைந்த வாழ்க்கைக் கதைகள், பாதுகாப்பான பிணைப்போடும் குணமடைதலோடும் தொடர்புடையவை (Siegel)."],[["ORDER",67,"simple"],"அத்தியாயங்கள் உள்ள ஒரு புத்தகம் போல உங்கள் வாழ்க்கையை எழுதுங்கள். ஒவ்வொன்றிலும் தேவன் எங்கே இருந்தார் என்று பாருங்கள்."],[["ORDER",68,"t"],"ஹம்மிங் & “வூ” மூச்சு"],[["ORDER",68,"time"],"2–3 நிமிடம்"],[["ORDER",68,"u"],"வேகத்தைக் குறைத்து அமைதியடைய, மூச்சை வெளிவிடும்போது நீண்ட, அதிர்வுள்ள ஒலிகளைப் பயன்படுத்துங்கள்."],[["ORDER",68,"steps",0],"மூக்கு வழியாக மென்மையாக மூச்சை உள்ளிழுங்கள்"],[["ORDER",68,"steps",1],"மூச்சை வெளிவிடும்போது, கப்பலின் மூடுபனி ஊதுகுழல் போல, ஹம் செய்யுங்கள் அல்லது தாழ்ந்த “வூஊஊ” ஒலி எழுப்புங்கள்"],[["ORDER",68,"steps",2],"உங்கள் நெஞ்சிலும் வயிற்றிலும் அதிர்வை உணருங்கள்"],[["ORDER",68,"steps",3],"5–10 மூச்சுகள் தொடருங்கள்"],[["ORDER",68,"steps",4],"நிதானித்து, எப்படி உணர்கிறீர்கள் என்று கவனியுங்கள்"],[["ORDER",68,"fixes",0,0],"எனக்கு வெட்கமாக இருக்கிறது"],[["ORDER",68,"fixes",0,1],"மெதுவாக ஹம் செய்யுங்கள், அல்லது காரில் அல்லது குளிக்கும்போது செய்யுங்கள்"],[["ORDER",68,"fixes",1,0],"எனக்குத் தலைசுற்றுகிறது"],[["ORDER",68,"fixes",1,1],"சிறிய ஒலிகளைப் பயன்படுத்துங்கள்"],[["ORDER",68,"fixes",2,0],"எனக்கு எதுவும் உணரவில்லை"],[["ORDER",68,"fixes",2,1],"இன்னும் நீண்ட, தாழ்ந்த ஒலிகளை முயலுங்கள்"],[["ORDER",68,"why"],"குரலுடன் நீண்ட நேரம் மூச்சை வெளிவிடுவது மூச்சை மெதுவாக்கி, வேகஸ் நரம்புடன் இணைந்த தசைகளைச் செயல்படுத்துகிறது. பாடுவது மற்றவர்களுடனான உறவுக்கும் உதவுகிறது."],[["ORDER",68,"simple"],"மூச்சை வெளிவிடும்போது ஹம் செய்யுங்கள் அல்லது நீண்ட “வூ” ஒலி எழுப்புங்கள். அந்த அதிர்வு உங்கள் உடலை அமைதிப்படுத்துகிறது."],[["ORDER",69,"t"],"பட்டாம்பூச்சி அணைப்பு & உங்களையே அணைத்துக்கொள்ளுதல்"]];
